INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0235', 'spa', 'Ir, irse, agotarse; verbo mayormente poético para partida, vagabundeo o agotamiento de recursos', 'Verbo que aparece casi exclusivamente en poesía, con el sentido de irse o consumirse. Su cognado arameo (אֲזַל) es la palabra cotidiana para ''ir'', lo cual revela cómo el hebreo reserva esta raíz para el estilo elevado. Deuteronomio 32:36 la emplea memorablemente para las fuerzas que ''se han acabado'', mientras que Job 14:11 describe las aguas que se evaporan del mar. El comprador que ''se va'' jactándose en Proverbios 20:14 ofrece una vívida escena comercial. Las traducciones en español — ''se acabó'', ''se ha ido'', ''se van'' — reflejan bien el abanico semántico entre partida y agotamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0236', 'spa', 'Verbo arameo que significa ir, caminar o viajar a un lugar; usado en Esdras y Daniel.', 'Este verbo arameo (cognado del hebreo halak) significa ''ir'' o ''viajar'' y aparece exclusivamente en las secciones arameas de Esdras y Daniel. Cubre tanto viajes consumados (''fue'', ''fuimos'', ''fueron'') como mandatos (''¡ve!''). Las formas españolas ''fue/fuimos/fueron'' reflejan bien el aspecto perfectivo presente en la mayoría de sus apariciones. Aunque solo sobreviven siete atestiguaciones en el texto bíblico, el verbo era común en el arameo imperial y en el uso rabínico posterior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0238', 'spa', 'Prestar oído, escuchar atentamente — verbo Hifil de audición atenta, casi exclusivamente poético, frecuentemente emparejado con שָׁמַע', 'Prestar oído, escuchar atentamente — verbo Hifil de audición atenta, casi exclusivamente poético, frecuentemente emparejado con שָׁמַע');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0241', 'spa', 'Oído, órgano de la audición; frecuentemente en ''a oídos de,'' es decir, ''en presencia/audiencia de.''', 'אֹזֶן designa el oído físico, el órgano de la audición, pero su uso bíblico más distintivo es la construcción preposicional בְּאָזְנֵי (''a oídos de''), que significa ''en la audiencia de'' o ''públicamente ante.'' Cuando Abraham negocia con los hititas la parcela para sepultar a Sara, la transacción se realiza ''a oídos de'' los testigos reunidos (Gn 23:10, 13, 16). El oído también figura en la ley ritual: se perfora la oreja del siervo para marcar servicio permanente (Ex 21:6), y se aplica sangre en la oreja derecha durante la consagración sacerdotal (Lv 8:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0247', 'spa', 'Ceñir, atar o equipar; usado en diversas conjugaciones para sujetar un cinturón o arma, ser revestido de fuerza y ceñirse para la acción. Un verbo fís', 'Ceñir, atar o equipar; usado en diversas conjugaciones para sujetar un cinturón o arma, ser revestido de fuerza y ceñirse para la acción. Un verbo físico vívido que va desde el acto práctico de ajustar un cinturón de cuero hasta la imagen teológica de Dios ciñendo a un guerrero con fuerza. En 2 Reyes 1:8, Elías es descrito como ''ceñido con un cinturón de cuero alrededor de sus lomos'', un detalle tan memorable que resuena en la descripción de Juan el Bautista. El Piel intensifica la acción: en el Salmo 18:32 y 39 (= 2 Sam 22:40), David alaba a Dios como aquel que lo ciñe de fuerza para la batalla. El Hitpael reflexivo aparece dramáticamente en el Salmo 93:1, donde el SEÑOR mismo ''se ha ceñido'' de majestad, y en Isaías 8:9, donde las naciones hostiles son desafiadas a ceñirse, solo para ser quebrantadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0249', 'spa', 'Ciudadano nativo de la tierra, con plenos derechos de pacto; figuradamente, un árbol que florece en su suelo natal. Derivado de una raíz que significa', 'Ciudadano nativo de la tierra, con plenos derechos de pacto; figuradamente, un árbol que florece en su suelo natal. Derivado de una raíz que significa ''levantarse, brotar'', esta palabra designa a alguien que ha brotado del suelo de la tierra: un israelita nacido en el país, en contraste con el גֵּר (forastero o extranjero residente). Los textos legales emparejan repetidamente a ambos, insistiendo en que la misma ley se aplica a los dos (Éx 12:19, 48-49; Lv 16:29; Nm 15:13, 29-30). En un uso poético aislado, el Salmo 37:35 compara al impío próspero con un árbol frondoso nativo profundamente arraigado en su propio suelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0250', 'spa', 'Ezraíta; adjetivo gentilicio que significa «descendiente de Zéraj», aplicado a Etán y Hemán', 'Este adjetivo gentilicio hebreo identifica a alguien como ezraíta, descendiente de Zéraj hijo de Judá. La designación aparece en los encabezados de dos salmos y en una referencia a la sabiduría de Salomón. 1 Reyes 4:31 (5:11 en hebreo) compara la sabiduría de Salomón con la de «Etán el ezraíta» y otros sabios célebres. El Salmo 88 se atribuye a «Hemán el ezraíta» y el Salmo 89 a «Etán el ezraíta». Según 1 Crónicas 2:6, tanto Etán como Hemán eran hijos de Zéraj, lo que los hace ezraítas. Estos hombres fueron reconocidos por su sabiduría y habilidad musical, sirviendo como músicos del templo en tiempos de David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0251', 'spa', 'Hermano (varón que comparte padres); por extensión, pariente, compatriota o hermanos nacionales.', 'En su núcleo, אָח es la palabra hebrea para un hermano varón —un hermano de sangre (Gn 4:2). Pero al igual que sus cognados en las lenguas semíticas (árabe أخ, asirio akhu, etiópico ekhw), se amplía naturalmente para abarcar parentesco más amplio: parientes tribales, connacionales israelitas y aliados de pacto. Cuando se llama a Lot ''hermano'' de Abraham siendo en realidad su sobrino (Gn 14:14), o cuando Moisés se dirige a todo Israel como ''hermanos'' (Dt 1:16), la palabra pasa de la biología a la solidaridad. Las glosas árabes distinguen útilmente إخوان (hermanos/cofrades) de أخ (hermano de sangre), confirmando este sentido relacional ampliado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0254', 'spa', 'brasero, recipiente portátil para quemar carbones encendidos', 'Recipiente portátil para fuego, usado como calefacción, que aparece únicamente en Jeremías 36 durante la escena invernal en que el rey Joacim quema el rollo con las profecías de Jeremías. El término proviene del egipcio, lo cual refleja el intercambio cultural de objetos domésticos en el antiguo Cercano Oriente. La narración subraya el fuego ardiente dentro de este brasero, que el rey emplea para destruir la palabra de Dios pedazo a pedazo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0256', 'spa', 'Acab -- nombre propio que significa ''hermano del padre'', principalmente el infame rey de Israel, tambien un falso profeta en Babilonia.', 'Acab -- nombre propio que significa ''hermano del padre'', principalmente el infame rey de Israel, tambien un falso profeta en Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0259', 'spa', 'Uno; primero; una vez; cada uno; unos pocos; once (compuesto con עָשָׂר).', 'El numeral hebreo fundamental אֶחָד significa ''uno'' y posee un peso teologico que trasciende con mucho la aritmetica. La declaracion del Shema de que el SENOR es אֶחָד (Dt 6:4) resuena a traves de cada aparicion — desde la ''una sola carne'' del matrimonio (Gn 2:24) hasta la vision escatologica de Zacarias de ''un solo SENOR y un solo nombre'' (14:9). Mas alla de su uso cardinal, esta versatil palabra funciona como ordinal (''primero''), distributivo (''cada uno''), marcador temporal (''una vez''), e incluso se combina con עָשָׂר para formar ''once.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0260', 'spa', 'juncos, plantas palustres de pantano (término colectivo para vegetación de zonas húmedas)', 'Término colectivo para los juncos o cañas que crecen en zonas pantanosas, tomado del egipcio como muchos nombres de plantas. Aparece en el sueño del faraón donde las vacas pacen entre los juncos junto al Nilo, y en la literatura sapiencial de Job, que pregunta si el junco puede crecer sin agua. La referencia en Oseas es textualmente incierta. Estas plantas palustres simbolizaban la abundancia ribereña de Egipto y servían como metáfora natural de la dependencia del agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0266', 'spa', 'Ahohita; adjetivo gentilicio que designa a los descendientes de Ahoah, guerreros de la guardia de elite de David.', 'Adjetivo patronimico que identifica a los miembros del clan de Ahoah, un benjaminita. Aparece exclusivamente en las listas militares de los valientes de David. Eleazar hijo de Dodo el ahohita (2 Sam 23:9; 1 Cr 11:12) y Zalmon/Ilai el ahohita (2 Sam 23:28; 1 Cr 11:29) figuraban entre los Treinta de elite. La uniformidad en las traducciones — ingles ''the Ahohite,'' espanol ''el ahohita,'' frances ''le Ahohite'' — refleja la funcion gentilicia directa de este termino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0268', 'spa', 'La espalda, la parte trasera o posterior; usado adverbialmente para ''hacia atrás'' o ''detrás'', temporalmente para ''después'', anatómicamente para la esp', 'La espalda, la parte trasera o posterior; usado adverbialmente para ''hacia atrás'' o ''detrás'', temporalmente para ''después'', anatómicamente para la espalda del cuerpo, y geográficamente para el occidente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0269', 'spa', 'Hermana, parienta femenina cercana; idiomáticamente, ''contraparte'' o ''una a otra'' referido a objetos emparejados.', 'En su sentido primario es un término de parentesco que designa a una hermana de sangre: Sara como media hermana de Abraham (Gn 20:12), Miriam como hermana de Aarón (Éx 15:20), Tamar como hermana de Absalón (2 S 13:1). Sin embargo, en un reducido grupo de pasajes la palabra adquiere un giro idiomático: las cortinas del tabernáculo se unen ''cada una a su hermana'' (Éx 26:3), y las alas de los querubines se tocan ''cada una a su hermana'' (Ez 1:9), un modismo de emparejamiento donde la ''hermana'' no es una persona sino una pieza correspondiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0270', 'spa', 'Agarrar, asir, tomar; en sentido figurado: ser presa del temor; tambien sujetar, tomar posesion o ser atrapado.', 'Agarrar, asir, tomar; en sentido figurado: ser presa del temor; tambien sujetar, tomar posesion o ser atrapado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0271', 'spa', 'Acaz — rey de Judá (c. 735-715 a.C.), hijo de Jotam, padre de Ezequías; nombre que significa ''él ha asido''', 'Acaz — rey de Judá (c. 735-715 a.C.), hijo de Jotam, padre de Ezequías; nombre que significa ''él ha asido''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0272', 'spa', 'Propiedad territorial mantenida como posesion hereditaria permanente, especialmente en la legislacion sacerdotal.', 'Propiedad territorial mantenida como posesion hereditaria permanente, especialmente en la legislacion sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0274', 'spa', 'Ocozías — nombre hebreo que significa ''Yah ha asido'', llevado por un rey de Israel y un rey de Judá', 'Ocozías — nombre hebreo que significa ''Yah ha asido'', llevado por un rey de Israel y un rey de Judá');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0281', 'spa', 'Ahías / Ahiyahu — nombre propio que significa ''hermano de Yah(vé),'' portado por un profeta, un sacerdote, un escriba y otros.', 'Ahías / Ahiyahu — nombre propio que significa ''hermano de Yah(vé),'' portado por un profeta, un sacerdote, un escriba y otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0283', 'spa', 'Ahío, nombre propio masculino portado por varios hombres, incluyendo el hermano de Uza que conducía el carro del arca.', 'Nombre propio masculino que significa ''fraternal'' o ''su hermano'', portado por al menos tres individuos en la Biblia hebrea. El más prominente es el hijo de Abinadab que, junto con su hermano Uza, conducía el carro nuevo que transportaba el arca de Dios desde Quiriat-jearim (2 Sam 6:3-4). El nombre también pertenece a dos benjaminitas enumerados en las genealogías de 1 Crónicas 8 y 9. Algunos manuscritos griegos antiguos leen esto como el sustantivo común ''sus hermanos'' en lugar de un nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0285', 'spa', 'Ahitob — nombre sacerdotal que significa ''mi hermano es bondad'', llevado por ancestros de sacerdotes clave de Israel. Ahitob (''mi hermano es bondad'') ', 'Ahitob — nombre sacerdotal que significa ''mi hermano es bondad'', llevado por ancestros de sacerdotes clave de Israel. Ahitob (''mi hermano es bondad'') designa al menos dos figuras sacerdotales importantes. El primero fue nieto de Elí a través de Finees y padre de Ahimélec, el sacerdote de Nob masacrado por Saúl (1 S 14:3; 22:9-20). El segundo fue padre de Sadoc, fundador de la dinastía sacerdotal sadoquita leal a David (2 S 8:17; 1 Cr 6:7-8). Las genealogías de Crónicas y Esdras-Nehemías trazan ambas líneas hasta el período postexílico (Neh 11:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0286', 'spa', 'Ajilud; nombre propio que quiza significa ''hermano de un nacido,'' padre de dos funcionarios bajo David y Salomon.', 'Nombre propio explicado tradicionalmente como ''hermano de un nacido'' o ''hermano de nino.'' La importancia principal de Ajilud radica en ser el padre de Josafat el cronista, quien sirvio bajo David (2 Sam 8:16; 20:24; 1 Cr 18:15) y continuo en el reinado de Salomon (1 R 4:3). Un segundo Ajilud es padre de Baana, uno de los doce gobernadores de distrito de Salomon (1 R 4:12). El nombre se mantiene con notable consistencia en las diversas tradiciones de traduccion, preservando la estructura consonantica hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0288', 'spa', 'Ahimelec (''mi hermano es rey''), nombre propio llevado por un sacerdote en Nob y un guerrero hitita. El nombre אֲחִימֶלֶךְ combina אָח (hermano) y מֶלֶ', 'Ahimelec (''mi hermano es rey''), nombre propio llevado por un sacerdote en Nob y un guerrero hitita. El nombre אֲחִימֶלֶךְ combina אָח (hermano) y מֶלֶךְ (rey), dando como resultado ''mi hermano es rey''. Su portador más prominente es el sacerdote en Nob que, sin saber que David huía de Saúl, le dio el pan consagrado y la espada de Goliat (1 Sam 21:1-9). Este acto de hospitalidad condujo a la masacre de los sacerdotes de Nob por Doeg el edomita bajo las órdenes de Saúl (1 Sam 22:9-20), un episodio crucial en las narrativas de David que Jesús mismo menciona en relación con los panes de la proposición (Mr 2:26). Un segundo Ahimelec, un hitita, sirvió entre los compañeros de David (1 Sam 26:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0289', 'spa', 'Ajimán; nombre propio de un gigante hijo de Anac y de un portero levita', 'Nombre propio masculino que posiblemente significa «mi hermano es un don», llevado por dos personajes distintos. El más destacado es uno de los tres gigantes anaceos que habitaban en Hebrón, a quienes los espías israelitas encontraron (Nm 13:22) y que Judá derrotó posteriormente (Jos 15:14; Jue 1:10). El segundo Ajimán es un portero levita mencionado en la comunidad postexílica de 1 Crónicas 9:17. La asociación de este nombre con los temibles anaceos lo hizo memorable en las tradiciones de la conquista de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0290', 'spa', 'Ahimaas — nombre que significa ''mi hermano es ira/consejo'', llevado por el hijo de Sadoc y el suegro de Saúl. Ahimaas (''mi hermano es ira'' o ''mi herma', 'Ahimaas — nombre que significa ''mi hermano es ira/consejo'', llevado por el hijo de Sadoc y el suegro de Saúl. Ahimaas (''mi hermano es ira'' o ''mi hermano es consejo'') es recordado sobre todo como el veloz hijo del sacerdote Sadoc, quien sirvió como mensajero leal de David durante la rebelión de Absalón. Junto con Jonatán hijo de Abiatar, transmitió información de inteligencia desde Jerusalén al campamento de David (2 S 15:27, 36; 17:17-20). Su famosa carrera contra el cusita para llevar a David la noticia de la muerte de Absalón es una de las escenas más vívidas de 2 Samuel (18:19-29). Un segundo Ahimaas fue suegro de Saúl (1 S 14:50).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0293', 'spa', 'Ajinoam (''mi hermano es deleite''), nombre de dos mujeres: la esposa de Saúl y la esposa de David de Jezreel.', 'Nombre propio femenino que significa ''mi hermano es deleite'' o ''mi hermano es gracia'', llevado por dos mujeres distintas en la Biblia hebrea. La primera es Ajinoam hija de Ajimaas, esposa del rey Saúl (1 S 14:50). La segunda es Ajinoam de Jezreel, una de las primeras esposas de David, quien lo acompañó durante sus años de fugitivo (1 S 25:43; 27:3; 30:5) y dio a luz a su primogénito Amnón (2 S 3:2; 1 Cr 3:1). El nombre se traduce con notable consistencia entre lenguas, reflejando su transparencia como compuesto teofórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0294', 'spa', 'Ahisamac (nombre propio: ''mi hermano ha sostenido'')', 'El nombre significa ''mi hermano ha sostenido'' e identifica al padre de Aholiab, quien junto con Bezaleel fue dotado por Dios para elaborar los utensilios del tabernáculo. Mientras Bezaleel descendía de Judá, el hijo de Ahisamac provenía de la tribu de Dan, demostrando que el Espíritu de Dios capacitó a artesanos de diversas tribus. El nombre refleja la práctica israelita de incorporar afirmaciones teológicas en los nombres personales, celebrando la solidaridad familiar bajo Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0295', 'spa', 'Ahiezer, ''mi hermano es ayuda''; nombre de un jefe danita y de un guerrero de David.', 'Nombre propio teofórico masculino que significa ''mi hermano es ayuda'', compuesto de אָח (''hermano'') y עֵזֶר (''ayuda''). Lo llevan dos individuos distintos: un jefe de la tribu de Dan que sirvió durante el período del desierto (Num 1:12; 2:25; 7:66, 71; 10:25), y un guerrero benjaminita que se unió a David en Siclag (1 Cr 12:3). El Ahiezer danita aparece repetidamente en las listas de censo y ofrendas tribales de Números, lo que indica su prominencia administrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0296', 'spa', 'Ahicam; ''mi hermano se ha levantado'', hijo de Safán, oficial de la corte bajo Josías que protegió al profeta Jeremías. Nombre propio hebreo que signif', 'Ahicam; ''mi hermano se ha levantado'', hijo de Safán, oficial de la corte bajo Josías que protegió al profeta Jeremías. Nombre propio hebreo que significa ''mi hermano se ha levantado''. Ahicam hijo de Safán sirvió como oficial de la corte bajo el rey Josías y formó parte de la delegación enviada a la profetisa Hulda tras el descubrimiento del Libro de la Ley (2 R 22:12, 14; 2 Cr 34:20). Su acto más notable fue proteger a Jeremías de la ejecución tras el controversial sermón del profeta en el templo (Jer 26:24). También se le recuerda como padre de Gedalías, a quien Nabucodonosor nombró gobernador sobre el remanente en Judá tras la caída de Jerusalén (2 R 25:22; Jer 39:14; 40:5-41:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0299', 'spa', 'Ahira; nombre propio que significa ''mi hermano es malo/un amigo,'' jefe de la tribu de Neftali.', 'Nombre del lider que represento a la tribu de Neftali durante el censo y la marcha por el desierto. Ahira hijo de Enan aparece en las narrativas altamente estructuradas de Numeros: el censo (Nm 1:15), la disposicion del campamento (Nm 2:29), las ofrendas de dedicacion del tabernaculo (Nm 7:78, 83) y el orden de marcha (Nm 10:27). El nombre se transliterado de forma identica como ''Ahira'' en espanol, ingles, frances y aleman, lo que refleja su transparente derivacion del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0302', 'spa', 'Ahitofel: el brillante pero traicionero consejero de David que se unió a la revuelta de Absalón. Nombre propio que significa ''mi hermano es necedad'', ', 'Ahitofel: el brillante pero traicionero consejero de David que se unió a la revuelta de Absalón. Nombre propio que significa ''mi hermano es necedad'', llevado por uno de los asesores más confiables de David. Ahitofel el gilonita era célebre por un consejo tan astuto que era ''como si se consultara la palabra de Dios'' (2 Sam 16:23). Sin embargo, traicionó a David uniéndose a la rebelión de Absalón, aconsejando al príncipe sobre la estrategia. Cuando su consejo fue rechazado en favor del de Husai, Ahitofel fue a su casa y se ahorcó (2 Sam 17:23), una de las salidas más dramáticas de la Biblia hebrea. Su nieto Eliam era padre de Betsabé (2 Sam 23:34), lo cual podría explicar en parte su defección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0309', 'spa', 'Demorar, tardar o detenerse; en Piel, ser lento en actuar o detener a alguien; relacionado con el arabe ''aḫḫara (posponer). El verbo ''aḥar aparece sol', 'Demorar, tardar o detenerse; en Piel, ser lento en actuar o detener a alguien; relacionado con el arabe ''aḫḫara (posponer). El verbo ''aḥar aparece solo una vez en Qal (Gen 32:5, ''me he demorado hasta ahora''), pero diecisiete veces en el Piel intensivo, donde expresa demora deliberada o permanencia prolongada. Jueces 5:28 lo empareja con bōshēsh (''llegar tarde'') cuando la madre de Sisara se pregunta por que tarda su carro. Los profetas lo emplean para el tiempo divino: ''mi salvacion no tardara'' (Isa 46:13; Hab 2:3). Proverbios 23:30 advierte contra quienes ''se demoran con el vino''. Un caso se distingue: Genesis 24:56, donde se pide a la familia de Laban que no ''detenga'' al siervo de Abraham, un uso transitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0310a', 'spa', 'Detrás de, tras; después de — posición espacial posterior o de persecución; sucesión temporal.', 'Preposición y adverbio versátil cuyos dos sentidos se dividen nítidamente entre lo espacial y lo temporal. En su acepción espacial, אַחַר sitúa a alguien detrás de otro o en su persecución: ''fue אַחַר de sus hermanos'' (Gn 37:17). En su acepción temporal, marca secuencia: ''después de estas cosas'' (Gn 15:1), ''después'' (Gn 10:18). El español distingue ambos sentidos con claridad: detrás de (espacial) frente a después de (temporal), lo cual confirma la realidad interlingüística de esta división semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0311', 'spa', 'después de ellos, después (preposición temporal aramea)', 'Expresión temporal aramea que significa ''después'' o ''después de ellos'', presente exclusivamente en las secciones arameas de Daniel. La frase suele señalar hacia eventos futuros, especialmente en contextos proféticos. Daniel emplea esta expresión al describir la visión de Nabucodonosor sobre lo que vendría ''después de estas cosas'' y al predecir un rey futuro que surgiría ''después de ellos''. Marca el despliegue secuencial de la soberanía divina a lo largo de la historia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0312', 'spa', 'Otro, otra, diferente; ocasionalmente ''siguiente'' o ''próximo'' en contextos temporales o secuenciales.', 'Adjetivo versátil que significa ''otro'' u ''otra'', abarcando tanto referentes adicionales como distintos. Aparece a lo largo de toda la Biblia hebrea, desde ''otra descendencia'' en Gn 4:25 hasta ''otros dioses'' en las advertencias del Deuteronomio. Un grupo menor de ocurrencias porta un matiz temporal: ''el año siguiente'' o ''la generación venidera'', donde el sentido pasa de la mera diferencia al ordenamiento secuencial, como en Gn 17:21 y Jl 1:3.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0314', 'spa', 'Ultimo, postrero, final; detras en lugar o tiempo; occidental; futuro, venidero.', 'Ultimo, postrero, final; detras en lugar o tiempo; occidental; futuro, venidero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0317', 'spa', 'Otro, otra; adjetivo arameo usado en las visiones de Daniel para distinguir reinos y bestias sucesivos.', 'Adjetivo arameo que significa ''otro'' u ''otra'', empleado en el libro de Daniel para señalar la sucesión de imperios mundiales en la visión apocalíptica. Cada vez que surge una nueva bestia o reino en la secuencia profética, esta palabra marca la transición. En Dan 2:39 introduce los reinos posteriores a Nabucodonosor, y en Dan 7:5-8 distingue cada bestia de la anterior. Las traducciones españolas captan bien su flexibilidad: ''otro'' para masculino y ''otra'' para femenino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0319', 'spa', 'La parte final o postrimeria; desenlace, destino; esperanza futura; posteridad o remanente; el extremo mas lejano de un lugar.', 'La parte final o postrimeria; desenlace, destino; esperanza futura; posteridad o remanente; el extremo mas lejano de un lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0321', 'spa', 'Otro; adjetivo arameo usado en Daniel para algo distinto o subsiguiente.', 'Adjetivo arameo que significa ''otro'' u ''otro distinto,'' presente en las secciones visionarias y profeticas de Daniel. Describe reinos, dioses y poderes categoricamente distintos de los que los precedieron. La evidencia multilingue es instructiva: el ingles traduce ''another,'' el espanol ''otro'' y el frances ''autre,'' todos captando el sentido de diferencia categorica. En Daniel 7:24 describe al cuerno final como ''otro'' que surge despues de los diez, un uso cargado de peso escatologico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0322', 'spa', 'Adverbio que significa hacia atrás, en dirección inversa; usado para describir retroceso físico o inversión de movimiento.', 'Adverbio formado con el sufijo direccional -it, que significa ''hacia atrás'' o ''en dirección inversa''. Sus siete apariciones abarcan momentos narrativos memorables: Sem y Jafet caminando hacia atrás para cubrir la desnudez de Noé (Gn 9:23), Elí cayendo de espaldas de su asiento al recibir la noticia de la captura del arca (1 S 4:18), y la sombra retrocediendo en el reloj de sol de Ezequías como señal divina (2 R 20:10-11; Is 38:8). El término expresa una inversión espacial concreta y vívida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0323', 'spa', 'Sátrapas; gobernadores provinciales persas que administraban los territorios del imperio aqueménida.', 'Préstamo del persa antiguo (khshatrapavan, ''protectores del reino'') que designa a los gobernadores provinciales de más alto rango en el Imperio aqueménida. El término aparece exclusivamente en los libros bíblicos tardíos de Esdras y Ester, reflejando el mundo administrativo persa en el que vivían los judíos del postexilio. En Ester, los sátrapas figuran entre los funcionarios que reciben y ejecutan los decretos reales, tanto el edicto genocida de Hamán (Est 3:12) como el contraedicto de Mardoqueo (Est 8:9; 9:3). Esdras 8:36 muestra a los exiliados que regresaron presentando órdenes reales a estos mismos funcionarios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0324', 'spa', 'Sátrapa; gobernador provincial persa, usado en las secciones arameas de Daniel y Esdras.', 'Préstamo arameo del persa antiguo (xšaθrapāvan, ''protector del reino'') que designa a los gobernadores provinciales de más alto rango en el Imperio Persa. En Daniel 3:2-3, los sátrapas encabezan la lista de funcionarios convocados a la dedicación de la imagen de oro de Nabucodonosor, y en Daniel 6:1-2, Darío nombra ciento veinte sátrapas bajo tres supervisores. El término señala la maquinaria administrativa del imperio que sirve de telón de fondo a la narrativa de Daniel. Las principales traducciones toman prestada o transliteran la palabra: español ''sátrapas'', francés ''satrape'', alemán ''Satrap''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0325', 'spa', 'Asuero (Jerjes) — el rey persa del libro de Ester, esposo de Vasti y luego de Ester', 'Asuero (Jerjes) — el rey persa del libro de Ester, esposo de Vasti y luego de Ester');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0328b', 'spa', 'Suavemente, despacio; adverbio de dulzura que expresa movimiento lento, quieto o tierno, y habla delicada.', 'Un hermoso adverbio construido sobre un sustantivo que significa ''dulzura,'' empleado para describir movimiento silencioso y habla tierna. El paso cuidadoso de Jacob con los rebanos que amamantan en Genesis 33:14 (''conducire despacio'') y las aguas de Siloe que fluyen suavemente en Isaias 8:6 son sus usos mas evocadores. La suplica de David de ''tratar con dulzura al joven Absalon'' (2 Sam 18:5) anade una profunda emocion paternal. El espanol capta bien su gama — ''despacio'' (lentamente), ''suavemente'' (con dulzura) — mostrando como la suavidad fisica y la ternura emocional convergen en una sola palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0329', 'spa', 'Espino, zarza espinosa (rhamnus); también Atad, topónimo de una era al otro lado del Jordán.', 'Designa un arbusto espinoso o zarza, célebre sobre todo en la fábula de Jotam (Jue 9:14-15), donde el olivo, la higuera y la vid rechazan la realeza, pero la humilde zarza la acepta con avidez y amenaza con fuego. El mismo arbusto espinoso aparece en Sal 58:9 como combustible que arde rápidamente. Como topónimo, designa la era de Atad (Gn 50:10-11), al este del Jordán, donde la procesión fúnebre de José lloró a Jacob durante siete días. En español, ''espino'' y ''zarza'' captan bien su carácter espinoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0331', 'spa', 'Cerrar, tapar, obstruir; de oídos (negarse a escuchar) o de ventanas (estrechas, enrejadas) en arquitectura del templo.', 'El verbo אָטַם describe la acción de cerrar u obstruir, y se aplica en dos ámbitos bien diferenciados. En el plano moral-auditivo, significa taparse los oídos —negarse a escuchar el clamor del pobre (Prov 21:13), sellar los labios con discreción (Prov 17:28) o cerrarse ante la corrupción moral (Isa 33:15). La víbora del Salmo 58:4 se tapa el oído ante el encantador. En el plano arquitectónico, el participio pasivo describe las ventanas estrechas o enrejadas del Templo de Salomón (1 Re 6:4) y del templo visionario de Ezequiel (Ez 40:16; 41:16, 26). El español capta bien la distinción con ''cerrar'' frente a ''estrechas''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0333', 'spa', 'Ater; nombre propio que significa quizá ''atador'' o ''cerrado'', llevado por jefes entre los judíos postexílicos.', 'Nombre propio que aparece en las listas censales de la época de la restauración en Esdras y Nehemías. Ater designa al menos dos grupos distintos: un cabeza de familia cuyos descendientes sumaban 98 entre los exiliados que retornaron (Esd 2:16; Neh 7:21) y una familia de porteros (Esd 2:42; Neh 7:45). Una persona llamada Ater figura también entre los firmantes de la renovación del pacto (Neh 10:17). El nombre podría significar ''atador'' o ''zurdo'', aunque su etimología sigue siendo incierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0335', 'spa', 'Partícula interrogativa: ¿dónde? ¿cuál? ¿cómo? — pregunta sobre ubicación, selección o manera', 'Partícula interrogativa: ¿dónde? ¿cuál? ¿cómo? — pregunta sobre ubicación, selección o manera');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0338', 'spa', 'chacales, hienas (carroñeros del desierto conocidos por sus aullidos)', 'Carroñeros aulladores que habitan lugares desolados, muy probablemente chacales, aunque el término puede abarcar también criaturas semejantes a las hienas. La palabra deriva de una raíz que sugiere aullido o lamento, evocando los gritos escalofriantes que resuenan entre ruinas y desiertos. Isaías y Jeremías emplean esta imagen para expresar devastación total: ciudades reducidas a hábitats propios únicamente de carroñeros salvajes. El cognado árabe identifica igualmente al chacal, animal que simboliza abandono y juicio divino en la profecía bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0339', 'spa', 'Isla, costa o litoral lejano; tierras habitables remotas al otro lado o junto al mar', 'Isla, costa o litoral lejano; tierras habitables remotas al otro lado o junto al mar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0341', 'spa', 'Enemigo, adversario; el que es hostil, ya sea rival personal, oponente nacional o antagonista divino.', 'El participio hebreo de la raíz álef-yod-bet (ser hostil) es el término bíblico estándar para designar al enemigo. Con 284 ocurrencias, abarca todo el espectro de la hostilidad: adversarios personales como Saúl contra David (1 S 18:29), enemigos nacionales que amenazan a Israel en el campo de batalla (Éx 15:6, 9), e incluso Dios mismo actuando como enemigo cuando su pueblo se rebela (Éx 23:22). La evidencia multilingüe es notablemente uniforme: todas las traducciones convergen en un solo equivalente, confirmando que el hebreo antiguo disponía de un término amplio e indiferenciado para cualquier agente hostil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0342', 'spa', 'Enemistad, hostilidad; animosidad profunda, personal o comunitaria, a veces descrita como perpetua.', 'Sustantivo femenino que expresa una hostilidad arraigada y aparece en momentos decisivos de la Escritura. Su primera mención en Génesis 3:15 — la enemistad entre la serpiente y la mujer — establece un conflicto cósmico en los cimientos mismos del relato bíblico. Números 35:21-22 lo emplea para distinguir el homicidio motivado por odio personal del homicidio accidental. Ezequiel habla dos veces de una ''enemistad antigua'' (אֵיבַת עוֹלָם) albergada por pueblos vecinos contra Israel (25:15; 35:5). Se trata de una hostilidad relacional que va mucho más allá de la ira momentánea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0343', 'spa', 'Calamidad, desastre, ruina repentina — desgracia devastadora como juicio divino o consecuencia de la maldad.', 'Calamidad, desastre, ruina repentina — desgracia devastadora como juicio divino o consecuencia de la maldad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0344', 'spa', 'halcón, gavilán, milano (ave rapaz conocida por su vista aguda)', 'Ave rapaz incluida entre las aves inmundas en la ley levítica, que abarca diversas especies de halcones y gavilanes. El término podría ser onomatopéyico, imitando el grito del ave. Levítico y Deuteronomio prohíben comerla «según su especie», lo que sugiere que varias especies caían bajo esta categoría. Job la menciona como ejemplo de visión extraordinaria, capaz de divisar su presa desde grandes alturas, simbolizando una percepción que supera la capacidad humana. Su aguda vista la convirtió en metáfora natural de una perspicacia que penetra lo oculto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0345', 'spa', 'Aiah, ''halcón''; nombre horita y padre de Rizpa, concubina de Saúl.', 'Nombre propio masculino que probablemente significa ''halcón'' o ''gavilán'', llevado por dos individuos en la Biblia hebrea. El primero es un horita, mencionado como hijo de Zibeón en las genealogías del territorio de Esaú (Gn 36:24; 1 Cr 1:40). El segundo, y más relevante narrativamente, es el padre de Rizpa, concubina de Saúl. Rizpa hija de Aiah desempeña un papel conmovedor en 2 Sam 3:7 y especialmente en 21:8-11, donde vela los cuerpos de sus hijos ejecutados hasta que David ordena darles sepultura digna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0346', 'spa', '¿Dónde? — adverbio interrogativo que pregunta por la ubicación, frecuentemente con fuerza retórica o acusatoria', '¿Dónde? — adverbio interrogativo que pregunta por la ubicación, frecuentemente con fuerza retórica o acusatoria');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0347', 'spa', 'Job -- el justo sufriente de la tierra de Uz, figura central del libro sapiencial que lleva su nombre.', 'Job -- el justo sufriente de la tierra de Uz, figura central del libro sapiencial que lleva su nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0348', 'spa', 'Jezabel; princesa fenicia y reina de Israel, esposa de Acab, que promovió el culto a Baal.', 'Jezabel; princesa fenicia y reina de Israel, esposa de Acab, que promovió el culto a Baal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0349a', 'spa', 'ekh -- !como! adverbio exclamativo e interrogativo de modo, asombro o lamento.', 'ekh -- !como! adverbio exclamativo e interrogativo de modo, asombro o lamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0349b', 'spa', 'Adverbio interrogativo-exclamativo: ''¿Como?'' o ''¡Como!'' que expresa modo o asombro; raramente ''¿Donde?'' en dialecto norteno. Formado a partir de la pa', 'Adverbio interrogativo-exclamativo: ''¿Como?'' o ''¡Como!'' que expresa modo o asombro; raramente ''¿Donde?'' en dialecto norteno. Formado a partir de la particula interrogativa ''ay y el demostrativo koh, este adverbio pregunta ''¿de que manera?'' con un matiz mas enfatico que el simple eikh. Aparece tanto en preguntas genuinas (Deut 1:12, ''¿Como puedo yo solo soportar vuestros problemas?''; Deut 7:17) como en exclamaciones de angustia (Isa 1:21, ''¡Como se ha convertido en ramera la ciudad fiel!''; Lam 1:1, ''¡Como esta sentada solitaria la ciudad!''). El libro de Lamentaciones toma su titulo hebreo de esta palabra. En dos ocurrencias en Cantar de los Cantares 1:7 funciona como ''¿donde?'', un uso paralelo al arameo eikha que sugiere coloracion dialectal nortena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0349c', 'spa', '¿Cómo? Exclamación interrogativa enfática que expresa consternación o intensidad emocional.', 'Partícula interrogativa compuesta formada por אֵי (¿dónde? ¿cómo?) y כָּכָה (así, de este modo), que produce un enfático ''¡¿Cómo?!'' cargado de fuerte emotividad. Aparece solo cuatro veces, en dos pares de ocurrencias. En Ester 8:6, la reina Ester exclama dos veces ''¿Cómo podré soportar ver...?'' al suplicar ante Asuero por la salvación de su pueblo. En Cantares 5:3, la amada pregunta dos veces ''¿Cómo habré de...?'' en su soñolienta reluctancia a levantarse y abrir la puerta. Ambos contextos emplean la palabra para expresar agitación interior: angustia en Ester, tierna vacilación en el Cantar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0352a', 'spa', 'Carnero; oveja macho, empleado prominentemente en sacrificios, tributos, alimentos y simbolismo profético.', 'El אַיִל es la oveja macho adulta, y sus 156 ocurrencias veterotestamentarias lo sitúan en la intersección del culto, la economía y la profecía. El carnero atrapado en el matorral se convierte en el sacrificio sustitutivo de Abraham en el Moria (Gn 22:13), estableciendo un paradigma de ofrenda provista por Dios. En el sistema levítico se prescribe para holocaustos, sacrificios por la culpa y la consagración sacerdotal (Éx 29:15-22). La visión de Daniel emplea un carnero con dos cuernos como símbolo del imperio medo-persa (Dn 8:3-4). Las traducciones convergen en el término estándar para oveja macho: carnero, bélier, Widder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0352b', 'spa', 'Pilar saliente, pilastra o jamba que flanquea una entrada o puerta, especialmente en la arquitectura del templo', 'Pilar saliente, pilastra o jamba que flanquea una entrada o puerta, especialmente en la arquitectura del templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0352c', 'spa', 'jefes, caudillos (derivado de ''carnero'' como líder del rebaño)', 'Término para designar líderes o caudillos, posiblemente derivado de la metáfora del carnero como animal que guía el rebaño. Aparece en contextos poéticos elevados que describen figuras prominentes entre las naciones. El Cántico de Moisés celebra el terror que se apoderó de «los caudillos de Moab» al paso de Israel. Ezequiel emplea el término para referirse a líderes prominentes o «poderosos» entre las naciones, aquellos que encabezan a sus pueblos como carneros delante del rebaño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0352d', 'spa', 'terebintos, encinas (árboles prominentes que señalaban sitios sagrados o significativos)', 'Término para árboles grandes y prominentes —probablemente terebintos o encinas— asociados con frecuencia a lugares de culto idolátrico en los textos bíblicos. Estos árboles marcaban sitios donde los israelitas practicaban vergonzosamente rituales sincretistas, quemando incienso bajo su sombra. Los profetas los invocan como símbolos de devoción extraviada y juicio venidero. La conexión con la prominencia y la altura puede vincular este uso con el sentido general de «líderes», pues estos árboles sobresalían en el paisaje tal como los caudillos sobresalían entre el pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0354', 'spa', 'Ciervo, venado — un macho de ciervo permitido como alimento limpio y utilizado como figura de gracia, anhelo y rapidez. El sustantivo אַיָּל (ʾayyal) ', 'Ciervo, venado — un macho de ciervo permitido como alimento limpio y utilizado como figura de gracia, anhelo y rapidez. El sustantivo אַיָּל (ʾayyal) designa un ciervo macho o venado, uno de los animales limpios en la ley dietética de Israel y una figura ricamente evocadora en la poesía hebrea. Deuteronomio enumera al ciervo junto con la gacela como alimento permitido (Dt 12:15, 22; 14:5), y la mesa de Salomón lo incluía (1 R 4:23). En el Salmo 42:1, el ciervo que jadea por las aguas se convierte en la sed del alma por Dios. El Cantar de los Cantares compara al amado con un joven ciervo que salta por los montes (Cnt 2:9). Isaías promete que el cojo «saltará como un ciervo» (Is 35:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0355', 'spa', 'Cierva o gacela hembra, usada en la poesía como figura de gracia, agilidad y paso seguro.', 'Este sustantivo femenino designa a la cierva —la hembra del ciervo— y aparece casi exclusivamente en la literatura poética y sapiencial. Neftalí es comparado con una cierva suelta que da hermosas palabras (Gn 49:21), y se alaba a Dios por hacer los pies veloces y seguros como los de una cierva (2 Sam 22:34; Sal 18:33; Hab 3:19). El Cantar de los Cantares conjura por las ''ciervas del campo'' (Cnt 2:7; 3:5). El sustantivo אַיָּלָה evoca consistentemente la gracia, la agilidad y la delicadeza en el imaginario bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0356', 'spa', 'Elón, nombre propio llevado por un hitita, un ancestro de clan zebulonita, un juez de Israel y una ciudad danita.', 'Nombre propio que significa ''encina'' o ''terebinto'', compartido por varias figuras bíblicas y una ciudad. Elón el hitita fue suegro de Esaú (Gn 26:34; 36:2). Elón hijo de Zabulón fundó un clan (Gn 46:14; Nm 26:26). Otro Elón de Zabulón sirvió como juez menor durante diez años (Jue 12:11-12). El nombre también designa una ciudad en Dan (Jos 19:43). La transliteración consistente entre idiomas refleja su fonología sencilla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0357', 'spa', 'Ajalón — ciudad levítica en el territorio de Dan, en el valle donde Josué ordenó a la luna detenerse. El topónimo אַיָּלוֹן (Ajalón), probablemente de', 'Ajalón — ciudad levítica en el territorio de Dan, en el valle donde Josué ordenó a la luna detenerse. El topónimo אַיָּלוֹן (Ajalón), probablemente derivado de אַיָּל (ciervo/venado), designa una ciudad en las colinas de la Sefela asignada a la tribu de Dan y posteriormente designada como ciudad levítica. Su fama descansa en la dramática orden de Josué: «Luna, detente sobre el valle de Ajalón» (Jos 10:12). Los amorreos retuvieron el control durante algún tiempo, ya que los danitas tuvieron dificultades para desposeerlos (Jue 1:35). Más tarde sirvió como ciudad fortificada bajo Roboam (2 Cr 11:10) y fue tomada por los filisteos en tiempos de Acaz (2 Cr 28:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0359a', 'spa', 'Eilat (Elat), ciudad portuaria en el extremo nororiental del mar Rojo (golfo de Áqaba).', 'Topónimo que designa una ciudad y puerto en el extremo norte del golfo de Áqaba, el brazo oriental del mar Rojo. El nombre probablemente deriva de una palabra que significa ''árbol(es) alto(s)'', en alusión a los palmerales de la región. Aparece en relación con la ruta de Israel por el desierto (Dt 2:8) y más tarde como ciudad portuaria estratégica disputada: Uzías la reconstruyó y Rezín la reconquistó (2 R 14:22; 16:6). Las traducciones interlingüísticas conservan de manera consistente el nombre semítico: en español ''Elat'', en francés ''Elath'', en alemán ''Elath''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0359b', 'spa', 'Elot, grafía alternativa de la ciudad portuaria de Eilat en el golfo de Áqaba.', 'Forma alternativa del topónimo Eilat (H0359a), con una terminación plural o femenina que podría reflejar el significado ''arboleda de árboles altos (palmeras)''. Esta grafía aparece en pasajes que describen la flota de Salomón en el puerto (1 R 9:26), la reconquista disputada bajo Rezín (2 R 16:6) y los relatos paralelos del Cronista (2 Cr 8:17; 26:2). La variación entre Eilat y Elot probablemente refleja convención dialectal o escribal, no dos localidades distintas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0361', 'spa', 'Pórtico, vestíbulo — la entrada cubierta o estructura con columnas del templo visionario de Ezequiel.', 'Pórtico, vestíbulo — la entrada cubierta o estructura con columnas del templo visionario de Ezequiel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0362', 'spa', 'Elim, oasis con doce fuentes y setenta palmeras; segunda estación israelita tras cruzar el mar Rojo.', 'Topónimo que significa ''terebintos'' o ''árboles grandes'', identificando la segunda estación en el desierto tras el cruce del mar por parte de Israel. Elim es recordado por sus doce fuentes de agua y setenta palmeras, un alivio bienvenido después de las aguas amargas de Mara. El sitio se identifica comúnmente con el Wadi Gharandel en el oeste del Sinaí. Su abundante provisión de agua lo convirtió en un punto de descanso natural, y los números específicos (doce y setenta) podrían tener resonancia simbólica con las estructuras tribales y de ancianos de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0363', 'spa', 'Árbol (arameo); un gran árbol en el sueño de Nabucodonosor que simboliza la extensión de su dominio.', 'Sustantivo arameo que significa ''árbol'', presente exclusivamente en Daniel 4 dentro de la célebre visión onírica de Nabucodonosor. El gran árbol que crecía hasta el cielo, visible desde los confines de la tierra, con aves anidando en sus ramas y bestias cobijándose bajo su sombra, representa al propio rey y su vasto imperio. Daniel interpreta la tala del árbol como juicio divino sobre la soberbia de Nabucodonosor. Este vocablo es distinto de los términos hebreos comunes para ''árbol'' y pertenece a las secciones de vocabulario arameo del libro de Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0365', 'spa', 'cierva, gacela hembra (símbolo de gracia y agilidad)', 'Cierva o venada hembra, celebrada en las Escrituras por su belleza, gracia y paso seguro. Aparece en comparaciones de agilidad y firmeza, especialmente en los Salmos, donde Dios hace que los pies del creyente sean «como los de la cierva» en las alturas. Proverbios la emplea como imagen del afecto conyugal, mientras Jeremías describe cómo incluso la cierva abandona a su cría recién nacida en medio de una sequía severa. El animal encarna tanto una tierna vulnerabilidad como una fortaleza notable, lo que lo convierte en símbolo versátil en la poesía hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0366', 'spa', 'imponente, temible, sobrecogedor (que inspira temor mezclado con reverencia)', 'Adjetivo que describe algo que inspira asombro o pavor, usado tanto para el poderío militar aterrador como para una belleza digna y casi abrumadora. Habacuc lo aplica a los caldeos, cuya sola presencia infundía terror en sus enemigos. El Cantar de los Cantares lo usa dos veces para describir la majestuosa belleza de la amada: ella es «imponente como ejércitos con sus estandartes», una expresión que mezcla atracción con poder sobrecogedor. El término captura esa respuesta de estremecimiento al encontrarse ante algo demasiado grande para abordarse con ligereza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0367', 'spa', 'Terror, pavor o miedo: el sobrecogimiento paralizante inspirado por Dios, los enemigos o la muerte; en una ocasion, idolos o imagenes aterradoras. Sus', 'Terror, pavor o miedo: el sobrecogimiento paralizante inspirado por Dios, los enemigos o la muerte; en una ocasion, idolos o imagenes aterradoras. Sustantivo femenino derivado de una raiz que transmite miedo visceral y crudo, presente mayormente en poesia y prosa elevada. Describe el pavor que cae sobre los pueblos por la presencia misma de Dios (Exod 15:16; 23:27; Deut 32:25), el terror de los enemigos (Jos 2:9; Isa 33:18), el temor que inspira un rey (Prov 20:2) y los ''terrores de la muerte'' que abruman al salmista (Sal 55:4-5). El misterioso ''pavor y gran oscuridad'' que cayo sobre Abraham (Gen 15:12) emplea esta misma palabra. En una ocurrencia singular (Jer 50:38), la evidencia multilingue diverge notablemente: se sugieren objetos concretos de terror mas que la emocion abstracta, probablemente imagenes de culto aterradoras asociadas con Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0368', 'spa', 'Emim (pueblo antiguo cuyo nombre significa ''terrores'' o ''los temibles'')', 'Pueblo antiguo que habitaba en la región de Moab antes de que los moabitas los desplazaran. Israel los reconocía como gigantes que infundían temor. Su nombre proviene de una raíz que significa ''terror'' o ''espanto'', reflejando su reputación intimidante. Génesis y Deuteronomio los clasifican junto a los anaceos, ambos grupos recordados por su estatura formidable. Como otros habitantes previos a la conquista, representan las naciones poderosas que Dios desplazó para dar lugar a sus pueblos elegidos, mostrando que ninguna fuerza humana puede resistir el propósito divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0369', 'spa', 'No hay, no existe, nada; partícula de inexistencia para negar ser, presencia o disponibilidad.', 'La partícula אַיִן (constructo אֵין) es la herramienta principal del hebreo para negar la existencia, el espejo oscuro de יֵשׁ (''hay''). Donde יֵשׁ afirma presencia, אֵין la niega: ''no hay rey en Israel'' (Jue 21:25), ''no hay Dios fuera de mí'' (Is 45:5). Se conjuga con sufijos pronominales creando un paradigma pseudoverbal — אֵינֶנִּי (''yo no soy''), אֵינְךָ (''tú no eres''), אֵינֶנּוּ (''él no es'') — fenómeno único entre los negadores semíticos. Más allá de la negación simple, אַיִן desarrolla un uso preposicional privativo (''sin'') y, en su forma absoluta, puede significar ''nada, nadie'', como cuando Isaías declara que Dios ''reduce a la nada a los príncipes'' (Is 40:23).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0370', 'spa', '¿De donde? Adverbio interrogativo de origen o procedencia, frecuentemente con fuerza retorica o poetica. El compuesto מֵאַיִן (de מִן ''de'' y אַיִן ''do', '¿De donde? Adverbio interrogativo de origen o procedencia, frecuentemente con fuerza retorica o poetica. El compuesto מֵאַיִן (de מִן ''de'' y אַיִן ''donde'') pregunta por el origen o la fuente. Mientras el sinonimo prosaico אֵי־מִזֶּה cumple la misma funcion en el habla cotidiana, מֵאַיִן lleva un tono mas elevado, a menudo retorico o poetico. Jacob pregunta a los pastores ''¿De donde sois?'' (Gen 29:4), Jose confronta a sus hermanos con ''¿De donde habeis venido?'' (Gen 42:7), y Moises exclama frustrado: ''¿De donde voy a sacar carne para todo este pueblo?'' (Num 11:13). En la literatura sapiencial la pregunta se vuelve profundamente teologica: ''¿De donde viene la sabiduria?'' (Job 28:12, 20). El salmista pregunta ''¿De donde vendra mi socorro?'' y responde: ''del SENOR'' (Sal 121:1-2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0374', 'spa', 'Efa — medida de áridos de aproximadamente 22 litros, usada para grano y harina, especialmente en ofrendas', 'Efa — medida de áridos de aproximadamente 22 litros, usada para grano y harina, especialmente en ofrendas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0375', 'spa', '¿Dónde? — adverbio interrogativo de lugar que exige la identificación de una ubicación o situación. El adverbio interrogativo אֵיפֹה (eifoh) pregunta ', '¿Dónde? — adverbio interrogativo de lugar que exige la identificación de una ubicación o situación. El adverbio interrogativo אֵיפֹה (eifoh) pregunta ''¿dónde?'' con una franqueza que a menudo conlleva un peso emocional o teológico más allá de la mera geografía. Cuando José pregunta a los pastores ''¿dónde están pastoreando?'' (Gn 37:16), la pregunta lanza la narrativa crucial de su descenso a Egipto. La suegra de Rut, Noemí, pregunta ''¿dónde espigaste hoy?'' (Rt 2:19), indagando en busca de evidencia del cuidado providencial. De manera más dramática, Dios desafía a Job: ''¿Dónde estabas tú cuando yo fundaba la tierra?'' (Job 38:4), usando la pregunta espacial para exponer el abismo entre el conocimiento divino y el humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0376', 'spa', 'Hombre, varón; esposo; cada uno — designa al individuo masculino, a la persona en general y al uso pronominal distributivo.', 'אִישׁ es la palabra hebrea para ''hombre'' en su sentido más concreto y encarnado: el ser humano masculino como distinto de la mujer (אִשָּׁה), del niño y del animal. Aparece por primera vez en el clímax del relato edénico: ''será llamada Mujer, porque del Hombre fue tomada'' (Gn 2:23), estableciendo el par אִישׁ/אִשָּׁה que resuena a lo largo de toda la Escritura. Pero אִישׁ es mucho más versátil que el español ''hombre'': sirve como término estándar para ''esposo'' (frecuentemente con sufijos posesivos), como pronombre indefinido (''un hombre'', ''cada uno'', ''cualquiera'') y en cadenas constructas que definen roles sociales (''hombres de guerra'', ''hombres de la ciudad''). La función distributivo-pronominal — ''cada uno a su tienda'' — es un rasgo característicamente semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0378', 'spa', 'Is-boset (''hombre de vergüenza''); hijo de Saúl que reinó brevemente sobre Israel en rivalidad con David.', 'Is-boset (''hombre de vergüenza''); hijo de Saúl que reinó brevemente sobre Israel en rivalidad con David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0380', 'spa', 'La pupila del ojo, usada figuradamente para algo precioso (''niña del ojo''); también la parte más oscura de la noche.', 'Sustantivo diminutivo que literalmente significa ''hombrecillo'', por el diminuto reflejo que se ve en la pupila ajena, empleado de dos maneras vívidas. Primero, como ''niña del ojo'' (Dt 32:10; Sal 17:8; Pr 7:2), expresa cuidado tierno y gran valor: Dios guarda a Israel como la niña de su ojo. Segundo, designa la hora más negra de la noche (Pr 7:9; 20:20), la oscuridad profunda donde merodea la adúltera. En español, ''niña del ojo'' conserva bellamente la etimología diminutiva, mientras que el sentido de oscuridad se expresa uniformemente con vocablos de negrura y tinieblas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0381', 'spa', 'hombre, varón; individuo masculino adulto, frecuentemente distinguido de la mujer o enfatizando la humanidad', 'Este término designa específicamente a un hombre individual a diferencia de la mujer, subrayando la masculinidad, la identidad individual o la condición de adulto pleno. Aparece con frecuencia en construcciones que destacan la distinción sexual, las relaciones matrimoniales o la acción individual. Mientras que otro vocablo hebreo denota la humanidad de manera colectiva, esta palabra se enfoca en la persona masculina particular. Describe esposos en relación con sus esposas, guerreros individuales en un ejército, hombres de determinado carácter o profesión. El plural puede significar ''hombres'' o incluso ''cada uno'', enfatizando la identidad individual dentro de un grupo. El contexto determina si se enfatiza la masculinidad, la individualidad o la humanidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0382', 'spa', 'hombre, varón; individuo masculino adulto, a menudo diferenciado de la mujer o resaltando la humanidad', 'Este término se refiere específicamente a un hombre individual como distinto de la mujer, poniendo énfasis en la masculinidad, la identidad personal o la plena condición de adulto. Frecuentemente aparece en construcciones que resaltan la diferencia de sexo, las relaciones conyugales o la iniciativa individual. A diferencia de otro término que designa la humanidad en su conjunto, esta palabra señala al varón particular. Describe a maridos respecto de sus esposas, a guerreros individuales dentro de un ejército, a hombres de carácter o profesión determinados. Su plural puede significar ''hombres'' o ''cada uno'', destacando la identidad individual dentro del grupo. El contexto define si predomina la masculinidad, la individualidad o la humanidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0383', 'spa', 'Hay, existe: particula existencial aramea equivalente al hebreo yēsh, con sufijos pronominales. La particula aramea ʾîṯay funciona como el existencial', 'Hay, existe: particula existencial aramea equivalente al hebreo yēsh, con sufijos pronominales. La particula aramea ʾîṯay funciona como el existencial ''hay'' o ''existen'', correspondiente al hebreo yēsh. Aparece exclusivamente en las secciones arameas de Daniel y Esdras, donde afirma o niega existencia con fuerza teologica. Cuando Daniel declara ''hay un Dios en el cielo que revela misterios'' (Dan 2:28), ʾîṯay fundamenta la declaracion en una realidad concreta. Con sufijos pronominales se vuelve personal: ''estamos'' (Dan 3:18), ''eres capaz'' (Dan 2:26). Sus cognados abarcan dialectos arameos — siriaco ʾīṯ, palmireno ʾyt — atestiguando una raiz existencial panarameica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0384', 'spa', 'Itiel (nombre propio, posiblemente ''Dios está conmigo'')', 'Nombre propio que aparece en Proverbios 30:1 (dos veces) y Nehemías 11:7, aunque el texto de Proverbios es notoriamente difícil. Muchos eruditos revocalizan el hebreo de Proverbios 30:1 para leer ''me he fatigado, oh Dios'' en lugar de tomarlo como nombre propio. Si es un nombre, probablemente significa ''Dios está conmigo''. La mención en Nehemías se refiere claramente a un antepasado benjamita. La incertidumbre en Proverbios resalta los desafíos de la transmisión textual hebrea y el papel de la vocalización en la determinación del significado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0385', 'spa', 'Itamar; el hijo menor de Aarón, ancestro de una línea sacerdotal que sirvió durante la era de Elí.', 'Itamar; el hijo menor de Aarón, ancestro de una línea sacerdotal que sirvió durante la era de Elí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0386', 'spa', 'Duradero, perenne, permanente; como sustantivo: fuerza, firmeza, o uno poderoso/perdurable. Adjetivo construido sobre un patrón elativo (comparable al', 'Duradero, perenne, permanente; como sustantivo: fuerza, firmeza, o uno poderoso/perdurable. Adjetivo construido sobre un patrón elativo (comparable al superlativo árabe) que transmite la idea de algo que nunca cesa ni cede. Describe célebremente el arroyo perenne en Amós 5:24: ''Corra el juicio como las aguas, y la justicia como arroyo que no se seca.'' En Gn 49:24, Jacob bendice a José con un arco que permanece ''en firmeza'', usando el sentido de sustantivo abstracto. El nombre del mes ''Etanim'' (1 R 8:2) conserva la palabra como marcador estacional para octubre-noviembre, el mes de los arroyos perennes tras las primeras lluvias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0387', 'spa', 'Etán — nombre propio que significa ''perdurable''; especialmente Etán el ezraíta, célebre por su sabiduría.', 'Etán (que significa ''perdurable'' o ''permanente'') es conocido principalmente como Etán el ezraíta, cuya sabiduría solo fue superada por la de Salomón (1 Re 4:31), y a quien se atribuye el Salmo 89 en su encabezado. Aparece en las genealogías de 1 Crónicas como hijo de Zéraj (1 Cr 2:6) y como cantor levítico junto con Hemán y Asaf (1 Cr 6:42-44; 15:17, 19). Las traducciones en diversas lenguas conservan fielmente el nombre: ''Etán'' en español y francés, ''Etan'' en alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0389', 'spa', 'Partícula discursiva: solo, solamente (restrictiva); ciertamente, en verdad (aseverativa); pero, sin embargo (adversativa).', 'Una partícula hebrea breve pero potente que tiñe cláusulas enteras con énfasis, restricción o contraste. Cuando Labán exclama ''¡Ciertamente hueso mío y carne mía eres tú!'' (Gn 29:14), אַךְ transmite la emoción del reconocimiento. Cuando Dios dice que Israel podrá comer carne ''solo que no comeréis la sangre'' (Gn 9:4), traza un límite tajante. Y cuando un salmista concede ''pero ciertamente bueno es Dios para Israel'' (Sal 73:1), pivota de la duda a la fe. El alemán capta bien el abanico con fürwahr, nur y aber, mientras que el español emplea ciertamente, solamente y pero: tres palabras distintas para una sola partícula versátil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0392', 'spa', 'Aczib, nombre de dos ciudades israelitas: una en la Sefelá de Judá y otra en la costa de Aser.', 'Topónimo que significa algo como ''engañoso'' o ''decepcionante'', quizá en alusión a un arroyo estacional que se seca. Dos ciudades distintas llevan este nombre: una en la Sefelá de Judá, mencionada entre las asignaciones territoriales de Judá (Jos 15:44) y referida en el juego de palabras de Miqueas sobre el engaño (Mi 1:14); y otra en la costa mediterránea, en el territorio de Aser (Jos 19:29; Jue 1:31), identificada con la posterior Ekdippa griega y el sitio moderno de ez-Zib al sur de Tiro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0393', 'spa', 'Cruel, feroz; describe veneno mortal, personas despiadadas o la aparente dureza de Dios', 'Adjetivo que transmite crueldad implacable y ferocidad visceral. Aparece en contextos sorprendentemente variados: el veneno letal de las serpientes en el cántico de Moisés (Dt 32:33), la majestad terrorífica del Leviatán que nadie osa provocar (Job 41:10), la acusación angustiada de Job de que Dios se ha vuelto cruel con él (Job 30:21), y la comparación estremecedora de las hijas de Jerusalén con avestruces que abandonan a sus crías (Lm 4:3). La palabra no nombra simple severidad, sino una dureza depredadora y desgarradora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0394', 'spa', 'Cruel, feroz, despiadado — describe a personas o fuerzas que actúan con dureza salvaje e implacable.', 'Este adjetivo pinta un cuadro vívido de severidad implacable. Proverbios advierte que incluso las misericordias de los impíos son crueles (12:10) y que un mensajero cruel será enviado contra el rebelde (17:11). Jeremías describe a los ejércitos enemigos como crueles y sin compasión (6:23; 50:42). Isaías lo emplea para referirse al terrible día del SEÑOR (13:9). El término אַכְזָרִי transmite una ferocidad despiadada que no admite matices: es la brutalidad sin misericordia llevada al extremo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0397', 'spa', 'Aquis; el rey filisteo de Gat ante quien David huyó dos veces de Saúl.', 'Aquis; el rey filisteo de Gat ante quien David huyó dos veces de Saúl.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0398', 'spa', 'Comer, consumir alimento; figuradamente devorar o consumir; en Nifal, ser comido; en Hifil, alimentar o dar de comer.', 'El verbo hebreo אָכַל es una de las palabras más frecuentes y viscerales del Antiguo Testamento, con más de 800 apariciones. En su raíz describe el acto humano universal de comer alimento — desde Adán y Eva en el jardín hasta el cordero pascual consumido con prisa. Sin embargo, este verbo cotidiano se convierte en una de las metáforas más poderosas de la Escritura: el fuego ''come'' (Éx 24:17), la espada ''devora'' (Dt 32:42) y la tierra ''consume'' a sus habitantes (Nm 13:32). El español refleja esta dualidad al distinguir entre comer y devorar/consumir. El arco teológico desde la comida prohibida en Edén (Gn 3:6) hasta la cena de la alianza en Éxodo 12 hace de este verbo un hilo conductor de toda la narrativa bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0399', 'spa', 'Comer o devorar; idiomáticamente, calumniar — verbo arameo para consumir alimento, devorar presa o acusar maliciosamente.', 'Este verbo arameo akal refleja su cognado hebreo en el significado de ''comer'', pero sus apariciones en Daniel muestran un rango vívido que va desde el consumo literal hasta la devoración apocalíptica y un llamativo modismo jurídico. Nabucodonosor come hierba como el ganado durante su locura (Dn 4:33), mientras que las bestias terribles de Daniel devoran a sus presas en visiones proféticas (Dn 7:5, 7, 19, 23). El modismo más colorido, akal qartsehon —literalmente ''comieron sus pedazos''— significa presentar acusaciones maliciosas o calumniar, usado cuando los caldeos denunciaron a los exiliados judíos ante el rey (Dn 3:8; 6:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0400', 'spa', 'Alimento, sustento, provisiones; el acto de comer o una comida; raramente, presa capturada por un depredador.', 'Alimento, sustento, provisiones; el acto de comer o una comida; raramente, presa capturada por un depredador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0402', 'spa', 'Alimento o sustento dado para comer; metaforicamente, presa o combustible entregado a la destruccion devoradora. El sustantivo femenino ''okhlah deriva', 'Alimento o sustento dado para comer; metaforicamente, presa o combustible entregado a la destruccion devoradora. El sustantivo femenino ''okhlah deriva del verbo ''akhal (''comer'') y aparece exclusivamente en la fuente Sacerdotal y en Ezequiel, siempre precedido por la preposicion le- (le''okhlah, ''para comida/para comer''). En Genesis 1:29-30 Dios designa toda planta verde le''okhlah — ''para comida'' — estableciendo la asociacion primaria de la palabra con el sustento provisto divinamente (cf. Gen 6:21; 9:3; Lev 11:39; 25:6). Ezequiel luego extiende la imagen oscuramente: la madera inutil de la vid es entregada le''okhlah al fuego (Ezeq 15:4, 6), los pueblos devastados se convierten en ''presa'' para las bestias (Ezeq 34:5, 8), y los ninos son pasados por el fuego le''okhlah (Ezeq 23:37).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0403', 'spa', 'Ciertamente, verdaderamente, en verdad (aseveracion enfatica); ocasionalmente adversativo: pero, sin embargo, no obstante. El adverbio ''aken funciona ', 'Ciertamente, verdaderamente, en verdad (aseveracion enfatica); ocasionalmente adversativo: pero, sin embargo, no obstante. El adverbio ''aken funciona como una particula aseverativa fuerte — mas enfatica que el simple ''akh — que tipicamente introduce una declaracion de reconocimiento sorpresivo o afirmacion solemne. La exclamacion de Jacob en Betel, ''¡Ciertamente el SENOR esta en este lugar!'' (Gen 28:16), marca el tono: ''aken senala el reconocimiento subito del hablante de una verdad antes inadvertida. Isaias lo emplea para la paradoja teologica: ''Verdaderamente tu eres un Dios que se oculta'' (Isa 45:15) y ''Ciertamente el llevo nuestras enfermedades'' (Isa 53:4). En dos casos (Sal 82:7; Sof 3:7) la particula gira hacia un sentido adversativo, introduciendo una contra-expectativa: ''pero/sin embargo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0406', 'spa', 'Labrador, agricultor, trabajador agrícola que labra la tierra; frecuentemente emparejado con viñadores.', 'Sustantivo masculino que designa a un labrador o agricultor, alguien cuyo sustento está ligado al cultivo de la tierra. Aparece frecuentemente junto a ''viñadores'' (koremim), pintando un cuadro de la economía agraria del antiguo Israel (Jer 31:24; 2 Cr 26:10; Jl 1:11). Jeremías usa el término tanto en el lamento por los labradores azotados por la sequía (14:4) como en la esperanza escatológica de una vida agrícola restaurada (31:24), mientras que Isaías vislumbra a extranjeros sirviendo como labradores de Israel en la era mesiánica (61:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0407', 'spa', 'Acsaf (ciudad cananea cuyo rey se opuso a Josué)', 'Ciudad cananea del norte de Israel, gobernada por un rey que se unió a la coalición contra Josué. Posteriormente, la ciudad quedó dentro del territorio tribal de Aser. Su ubicación exacta sigue siendo debatida: las propuestas van desde sitios cercanos a Tiro hasta localidades más al sur. El nombre aparece en registros egipcios, lo que confirma su prominencia antigua. Como muchas ciudades cananeas mencionadas en Josué, Acsaf representa los poderes establecidos que Israel enfrentó al entrar en la tierra, reinos aparentemente formidables que cayeron ante los propósitos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0408', 'spa', 'Partícula negativa de prohibición o deseo: ''no hagas, que no''; también ''no'' rotundo o negación retórica.', 'Partícula de negación subjetiva que expresa deseos, mandatos y prohibiciones en lugar de enunciar hechos desnudos. Donde לֹא niega categóricamente (''no es''), אַל ruega o prohíbe (''¡que no sea!''). Aparece abrumadoramente con formas yusivas y cohortativas — el clásico אַל־תִּירָא ''¡no temas!'' de Génesis 15:1 es su uso emblemático. Ocasionalmente funciona como un ''no'' rotundo e independiente (Jue 19:23) o incluso expresa ''nada, vanidad'' en contextos poéticos como Job 24:25. Las traducciones al español captan la fuerza prohibitiva con ''no'' seguido de subjuntivo, mientras que el alemán refleja su vinculación sintáctica con formas infinitivas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0409', 'spa', 'Partícula prohibitiva aramea: ''no'', ''que no'' — usada con el imperfecto para expresar prohibición', 'Adverbio arameo de prohibición, funcionalmente equivalente al hebreo bíblico אַל. Aparece exclusivamente en las secciones arameas de Daniel, donde introduce mandatos de abstenerse de una acción. Daniel insta a Arioc a no destruir a los sabios de Babilonia (Dn 2:24), a Nabucodonosor se le dice que no deje que el sueño lo perturbe (Dn 4:19), y la reina le dice a Belsasar que no permita que sus pensamientos lo aterroricen (Dn 5:10). A pesar de su breve aparición, carga un peso narrativo considerable en cada escena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0410', 'spa', 'Dios (El); vocablo semítico genérico para deidad; también ''poderoso, poder''; en epítetos divinos (El Shaddai, El Elyon).', 'אֵל es la palabra más antigua y elemental para Dios en las lenguas semíticas, atestiguada en acadio (ilu), ugarítico, fenicio y árabe (ilah) mucho antes de su uso bíblico hebreo. En la Biblia hebrea funciona principalmente como nombre o título del Dios verdadero de Israel, a menudo en contextos poéticos y arcaicos. Aparece en algunos de los epítetos compuestos más exaltados de la Escritura: El Shaddai (''Dios Todopoderoso'', Gn 17:1), El Elyon (''Dios Altísimo'', Gn 14:18-22), El Olam (''Dios Eterno'', Gn 21:33), El Roi (''Dios que ve'', Gn 16:13). No obstante, la palabra conserva también un sentido más genérico y antiguo: puede significar ''un dios'' en general, ''poderoso'' aplicado a seres humanos o ángeles, o simplemente ''poder, fuerza'' en paralelismo poético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0411', 'spa', 'Estos, estas — pronombre demostrativo plural que señala personas o cosas en el contexto inmediato.', 'Variante ortográfica arcaica del más frecuente אֵלֶּה (''estos/estas''), que funciona como pronombre demostrativo plural. Aparece tanto en Génesis como en Deuteronomio para indicar personas, lugares o cosas específicas dentro del discurso. Con el artículo (הָאֵל), adquiere un valor enfático: ''estos mismos''. El español lo traduce como ''estos/estas'', cumpliendo una función puramente referencial y deíctica sin matices adicionales, al igual que ''ces'' en francés y ''diese'' en alemán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0413', 'spa', 'a, hacia; en, dentro de; sobre; contra; por, acerca de; con, entre', 'La preposicion hebrea mas comun de movimiento dirigido, con mas de 5.500 apariciones. Su significado nuclear --movimiento hacia una persona, lugar u objetivo-- subyace en practicamente toda escena narrativa donde alguien va, envia, habla, da o se vuelve. A diferencia de la mas amplia ב (en) o על (sobre), אֵל codifica especificamente direccionalidad: la trayectoria del hablante al destino. Sin embargo, el contexto la desplaza hacia territorio hostil (''contra''), usos de proposito (''por, acerca de'') e incluso compania (''con, entre''). El cognado arabe ʾilā confirma el nucleo direccional. Esta unica silaba es el tejido conectivo de la narrativa hebrea, uniendo actores con sus destinatarios a lo largo de miles de clausulas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0415', 'spa', 'dios, poderoso; ser divino o alguien que posee poder y autoridad extraordinarios', 'Esta forma más breve del vocablo para Dios expresa poder y majestad más que el nombre relacional del pacto. La poesía la emplea extensamente, a menudo con términos calificativos: ''Dios de Israel'', ''Dios poderoso'', ''Dios Todopoderoso''. Ocasionalmente puede aplicarse a gobernantes o jueces humanos por extensión del concepto de poder, aunque tal uso es raro y debatido. Aparece en títulos divinos compuestos y enfatiza el poder trascendente. Su brevedad la hace especialmente apta para la poesía, donde alterna con nombres divinos más extensos manteniendo el enfoque en la fuerza y la soberanía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0416', 'spa', 'dios, poderoso; ser divino o quien posee poder y autoridad extraordinarios', 'Esta forma abreviada del término para Dios comunica poder y grandeza en lugar del nombre relacional de la alianza. Se usa ampliamente en la poesía, con frecuencia acompañada de expresiones calificativas como ''Dios de Israel'', ''Dios fuerte'' o ''Dios Omnipotente''. En casos excepcionales puede referirse a gobernantes o jueces humanos por extensión del concepto de poder, si bien este empleo es infrecuente y discutido. Forma parte de títulos divinos compuestos y subraya el poder trascendente. Su concisión resulta especialmente adecuada para el verso, donde se alterna con nombres divinos más largos sin perder el énfasis en la fortaleza y la soberanía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0417', 'spa', 'Granizo, piedras de granizo (precipitación helada usada en el juicio divino)', 'Piedras de granizo de gran tamaño, invocadas especialmente en las profecías de juicio de Ezequiel. El término es un préstamo del árabe, relacionado con el yeso o el alabastro, quizás por la apariencia pálida y pétrea del granizo. Ezequiel emplea esta imagen en oráculos contra los falsos profetas y en la batalla culminante contra Gog, donde el granizo se une al fuego, al azufre y a la lluvia torrencial como instrumentos de la ira divina. La imagen evoca la séptima plaga de Egipto y otros casos en los que Dios usa el clima como arma para ejecutar su juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0418', 'spa', 'Madera de algum (madera importada, posiblemente sándalo o enebro)', 'Madera importada, probablemente del Líbano u Ofir, utilizada en la construcción del templo y el palacio de Salomón. Su identificación botánica exacta sigue siendo incierta: las propuestas incluyen sándalo, enebro o pino rojo. Crónicas la menciona junto a cedros y cipreses del Líbano, y también como importación preciada de Ofir junto con oro y gemas. La doble aparición (H0418 algum en Crónicas, H0484 almug en Reyes para el mismo material) representa variantes ortográficas del mismo préstamo extranjero, lo que ilustra cómo los bienes comerciales exóticos a veces recibían transliteraciones inconsistentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0422', 'spa', 'Jurar o conjurar (Qal/Hifil); también maldecir o pronunciar una imprecación.', 'Verbo que abarca los actos solemnes de juramento y maldición. En su sentido primario, describe el acto de obligarse a sí mismo o a otro mediante un juramento ante Dios, ya sea en la celebración de un pacto (Os 4:2; 10:4), en procedimientos legales (1 R 8:31 = 2 Cr 6:22) o en una orden militar (1 S 14:24, Hifil). La crítica profética de Oseas denuncia los falsos juramentos de Israel como traición al pacto. En Jue 17:2, el verbo se desplaza hacia la maldición hostil: la madre de Micaía ''maldijo'' la plata robada, un acto imprecatorio distinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0423', 'spa', 'Maldición o imprecación, especialmente automaldición condicional; juramento solemne o pacto jurado; adjurar o poner bajo juramento (Hifil).', 'Maldición o imprecación, especialmente automaldición condicional; juramento solemne o pacto jurado; adjurar o poner bajo juramento (Hifil).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0424', 'spa', 'Terebinto — un árbol caducifolio grande usado como punto de referencia y lugar de reunión sagrado en el antiguo Israel. Elá designa el terebinto (Pist', 'Terebinto — un árbol caducifolio grande usado como punto de referencia y lugar de reunión sagrado en el antiguo Israel. Elá designa el terebinto (Pistacia terebinthus), una especie caducifolia resistente que puede alcanzar gran edad y tamaño impresionante en las tierras altas de Palestina. En la narrativa bíblica, terebintos individuales sirven como hitos memorables: el árbol cerca de Siquem donde Jacob enterró los dioses extranjeros (Gn 35:4), el de Ofrá bajo el cual el ángel del SEÑOR se apareció a Gedeón (Jue 6:11, 19) y el fatídico árbol cuyas ramas atraparon a Absalón (2 S 18:9-14). Textos proféticos asocian los terebintos con el culto idolátrico (Is 1:29; Os 4:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0425', 'spa', 'Ela — nombre propio llevado por varios personajes del AT, incluyendo un rey de Israel y un jefe edomita. Nombre propio hebreo que significa ''terebinto', 'Ela — nombre propio llevado por varios personajes del AT, incluyendo un rey de Israel y un jefe edomita. Nombre propio hebreo que significa ''terebinto'', llevado por al menos cinco personajes biblicos distintos. El mas prominente es Ela hijo de Baasa, quien reino brevemente sobre Israel antes de ser asesinado por Zimri (1 Rey 16:6-14). Otro Ela fue el padre de Oseas, el ultimo rey del reino del norte (2 Rey 15:30; 17:1; 18:1, 9). El nombre tambien designa a un jefe de Edom en la genealogia de Esau (Gen 36:41 = 1 Cro 1:52), un hijo de Caleb (1 Cro 4:15) y un descendiente benjaminita de Uzi (1 Cro 9:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0426', 'spa', 'Dios o deidad (arameo); usado para el Dios de Israel y tambien para dioses paganos en Daniel y Esdras.', 'Dios o deidad (arameo); usado para el Dios de Israel y tambien para dioses paganos en Daniel y Esdras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0428', 'spa', 'estos, estas — pronombre demostrativo plural de proximidad que senala un grupo de personas o cosas mencionadas', 'אֵלֶּה es el demostrativo plural por excelencia del hebreo biblico, con 746 apariciones para senalar grupos de personas, naciones, leyes, eventos u objetos. Funciona como el plural de זֶה (''este'') y con frecuencia encabeza resumenes genealogicos (''estos son los descendientes de'') y catalogos legales (''estos son los estatutos''). Sus combinaciones preposicionales --כָּאֵלֶּה (''como estos''), בָּאֵלֶּה (''entre estos''), מֵאֵלֶּה (''de estos'')-- son extensiones puramente sintacticas de la misma funcion deictica. La correspondencia interlingüistica es uniforme: espanol ''estos/estas'', frances ''ces'', aleman ''diese''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0430', 'spa', 'Dios (el Dios de Israel); dioses (deidades paganas); un dios o diosa (deidad extranjera). Forma plural mayestatica de eloah.', 'אֱלֹהִים es una de las palabras mas notables de cualquier lengua: un sustantivo morfologicamente plural que, en la gran mayoria de sus apariciones, designa al Dios unico de Israel y concuerda con verbos y adjetivos en singular. Esta paradoja gramatical ha generado milenios de reflexion teologica. En su sentido dominante, es sencillamente la forma estandar de decir ''Dios'' en la narrativa, la ley y la poesia hebreas: ''En el principio creo Dios'' (Gn 1:1). Pero la misma forma cumple tambien trabajo genuinamente plural al referirse a los dioses de las naciones --''no tendras dioses ajenos delante de mi'' (Ex 20:3)-- e incluso puede designar a una sola deidad extranjera como Dagon o Astoret.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0431', 'spa', '¡He aquí! Interjección aramea que introduce escenas vívidas en las visiones de Daniel.', 'Partícula exclamativa aramea empleada exclusivamente en el libro de Daniel para presentar elementos impactantes dentro de sueños y visiones. Aparece siempre como וַאֲלוּ (''¡y he aquí!''), creando una pausa dramática que dirige la atención del lector hacia lo que sigue: una gran estatua (Dn 2:31), un árbol imponente (Dn 4:10), un vigilante que desciende (Dn 4:13) y un cuerno pequeño con ojos humanos (Dn 7:8). Esta fuerza demostrativa confiere a las visiones de Daniel una vivacidad casi cinematográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0433', 'spa', 'Dios o un dios; forma singular poetica especialmente frecuente en Job, tambien usada para deidades paganas en textos biblicos tardios.', 'Dios o un dios; forma singular poetica especialmente frecuente en Job, tambien usada para deidades paganas en textos biblicos tardios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0436', 'spa', 'Encina o terebinto, árbol grande asociado a sitios sagrados y usado frecuentemente en topónimos bíblicos.', 'Sustantivo que designa un árbol grande y prominente, ya sea una encina o un terebinto, frecuentemente vinculado a lugares sagrados, santuarios y encuentros divinos en los relatos patriarcales. La «encina de Moré» en Siquem (Gn 12:6) fue el lugar donde Abram recibió por primera vez la promesa de Dios en Canaán, y las «encinas de Mamre» (Gn 13:18; 14:13; 18:1) se convirtieron en la morada prolongada de Abraham y en el escenario de la visitación angélica. La identificación botánica exacta sigue siendo objeto de debate académico entre la encina y el terebinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0437', 'spa', 'Encina (género Quercus), símbolo de fortaleza, majestuosidad y resistencia en la imaginería bíblica.', 'La encina (אַלּוֹן) ocupa un lugar destacado tanto en la narrativa como en la poesía profética. Marca el sitio de sepultura de Débora, nodriza de Rebeca, bajo la «encina del llanto» en Betel (Gn 35:8). Los profetas la invocan como símbolo de fortaleza imponente: las encinas de Basán representan el orgullo ante el juicio de Dios (Is 2:13; Zac 11:2), y Oseas condena la adoración idolátrica bajo las encinas (Os 4:13). La Septuaginta traduce con drys, confirmando la identificación con el género Quercus y no con el terebinto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0441a', 'spa', 'Uno domesticado o familiar; de ahí amigo íntimo, compañero cercano, o (por otra derivación) ganado/bueyes.', 'Construida sobre la raíz álef-lámed-pe, que evoca la idea de domesticar y familiarizar, esta palabra abarca un rango sorprendentemente cálido. En su núcleo describe al íntimo de confianza: el amigo más cercano que un vecino (Mi 7:5), el confidente cuya traición hiere más profundamente (Sal 55:13-14). Proverbios 2:17 la aplica al esposo como «compañero de su juventud», y Jeremías 3:4 la usa audazmente para YHWH mismo como esposo-amigo de Judá. Una aparición en Jeremías 11:19 conserva el sentido adjetival más antiguo: «un cordero manso llevado al matadero». Un tercer uso en el Salmo 144:14 probablemente se relaciona con el homónimo אֶלֶף (ganado), describiendo bueyes bien cargados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0441b', 'spa', 'alluph -- jefe, líder de clan; un cabecilla tribal, especialmente de los clanes edomitas', 'alluph -- jefe, líder de clan; un cabecilla tribal, especialmente de los clanes edomitas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0444', 'spa', 'corromperse, volverse depravado (deterioro moral y espiritual)', 'Verbo que aparece solo en Nifal (forma pasiva/reflexiva) y describe el proceso de corromperse o volverse moralmente depravado. La raíz evoca la imagen de algo que se agria o se echa a perder, como leche que se descompone: una metáfora vívida de la decadencia ética. Los Salmos lo emplean en paralelo con otros términos de perversión y maldad, subrayando la corrupción universal de la humanidad. Job lo aplica al individuo que bebe la iniquidad como agua. La raíz cognada en árabe transmite confusión y desorden, capturando el caos que la corrupción introduce en la vida moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0445', 'spa', 'Eljanán, nombre propio (''Dios ha sido misericordioso''), llevado por dos guerreros de élite de David', 'Nombre teofórico que significa ''Dios ha sido misericordioso'', portado por dos guerreros del círculo íntimo de David. Un Eljanán hijo de Jaaré-Oregim es acreditado con haber matado a un campeón filisteo en Gob (2 S 21:19; cf. 1 Cr 20:5, donde la víctima es Lahmi, hermano de Goliat). Otro Eljanán hijo de Dodó, de Belén, aparece en la lista de los Treinta de David (2 S 23:24; 1 Cr 11:26). Los cognados fenicios y asirios del nombre (Baalhanan) confirman su amplio uso semítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0446', 'spa', 'Eliab (''mi Dios es padre''); nombre de varias figuras del AT, incluyendo al hermano mayor de David y líderes tribales.', 'Eliab (''mi Dios es padre''); nombre de varias figuras del AT, incluyendo al hermano mayor de David y líderes tribales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0447', 'spa', 'Eliel — nombre personal teofórico que significa ''mi Dios es Dios'', llevado por al menos nueve hombres en Crónicas. El nombre אֱלִיאֵל (Eliel) combina ', 'Eliel — nombre personal teofórico que significa ''mi Dios es Dios'', llevado por al menos nueve hombres en Crónicas. El nombre אֱלִיאֵל (Eliel) combina אֵל (Dios) dos veces en la construcción ''mi Dios es Dios'', una confesión de devoción exclusiva. Lo portan múltiples individuos en las genealogías y listas militares del Cronista, lo que dificulta la identificación precisa. Entre los portadores notables se incluyen un jefe de clan manasita (1 Cr 5:24), dos benjaminitas (1 Cr 8:20, 22), al menos dos de los valientes guerreros de David (1 Cr 11:46-47), un combatiente gadita (1 Cr 12:12) y levitas involucrados en el traslado del arca (1 Cr 15:9, 11). Tanto en español como en inglés, ''Eliel'' se transliteran sin alteración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0450', 'spa', 'Eliada, nombre propio (''Dios sabe''), llevado por un hijo de David y otras figuras bíblicas', 'Nombre teofórico que significa ''Dios sabe'', compuesto de אֵל (Dios) y יָדַע (saber). Lo llevan al menos tres individuos: un hijo de David nacido en Jerusalén (2 S 5:16; 1 Cr 3:8), llamado también Beeliada (''el Señor sabe'') en 1 Cr 14:7; el padre de Rezón, adversario de Salomón (1 R 11:23); y un comandante militar benjaminita bajo Josafat (2 Cr 17:17). La variante Beeliada, que sustituye אֵל por בַּעַל, refleja probablemente la sensibilidad escribal posterior hacia el nombre Baal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0451', 'spa', 'Cola gorda de la oveja, la gruesa cola grasa apreciada en las ofrendas sacrificiales.', 'Se refiere a la característica cola grasa de la oveja de cola ancha (Ovis laticaudata), común en el antiguo Cercano Oriente, un corte de grasa tan considerable que podía pesar varios kilos. En contextos sacrificiales aparece junto a la grasa general (חֵלֶב), lo que la distingue como una porción especialmente valorada ofrecida a Dios. Sus cinco apariciones se concentran en las instrucciones rituales de Éxodo y Levítico (Éx 29:22; Lv 3:9; 7:3; 8:25; 9:19), subrayando su función como elemento sacrificial dedicado y no como alimento ordinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0452', 'spa', 'Elías -- el profeta de Tisbé cuyo nombre significa ''mi Dios es Yahvé'', campeón contra el culto a Baal', 'Elías -- el profeta de Tisbé cuyo nombre significa ''mi Dios es Yahvé'', campeón contra el culto a Baal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0453', 'spa', 'Elihú — nombre hebreo que significa ''Él es mi Dios'', llevado por el joven interlocutor de Job y otras cuatro figuras del AT. El nombre propio אֱלִיהוּ', 'Elihú — nombre hebreo que significa ''Él es mi Dios'', llevado por el joven interlocutor de Job y otras cuatro figuras del AT. El nombre propio אֱלִיהוּ (Elihú), que significa ''Él es mi Dios'', es conocido sobre todo por el joven buzita que interviene en Job después de que los tres amigos mayores se quedan en silencio. Pronuncia cuatro discursos (Job 32-37) defendiendo la justicia y soberanía de Dios, argumentando que el sufrimiento puede tener un propósito redentor en lugar de indicar culpa. Sus discursos sirven de puente entre los argumentos fallidos de los amigos y la teofanía de Dios desde el torbellino. El mismo nombre pertenece al bisabuelo de Samuel (1 Sam 1:1) y a varias figuras de la época davídica (1 Cr 12:20; 26:7; 27:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0454b', 'spa', 'Elyoenai (''mis ojos están hacia Dios''), nombre propio de varios hombres en Crónicas y Esdras-Nehemías.', 'Nombre propio masculino que significa ''mis ojos están hacia Dios'', expresando una dependencia devota del Señor. Lo llevan al menos cinco individuos en los registros genealógicos y postexílicos: un descendiente de David (1 Cr 3:23-24), un jefe simeonita (1 Cr 4:36), un benjaminita (1 Cr 7:8), y dos o tres sacerdotes o laicos en tiempos de Esdras (Esd 10:22, 27; Neh 12:41). La ligera variación ortográfica entre Elyoenai y Elyoenay refleja la fluidez ortográfica normal del hebreo bíblico tardío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0457', 'spa', 'Cosa sin valor, idolo; concretamente una deidad pagana o imagen tallada, abstractamente vanidad o total insuficiencia. Derivado de una raiz que sugier', 'Cosa sin valor, idolo; concretamente una deidad pagana o imagen tallada, abstractamente vanidad o total insuficiencia. Derivado de una raiz que sugiere debilidad o nulidad, elil es un termino devastadoramente despectivo para los dioses paganos. Los profetas y salmistas lo emplean como polemica: los dioses de las naciones son meros elilim, ''naderías'' (Sal 96:5; 1 Cro 16:26). Puede incluso haber un juego de palabras deliberado con el (''Dios''), como diciendo que estos supuestos dioses son en realidad ''no-dioses''. En algunos pasajes emerge el sentido abstracto: el pastor inutil de Zacarias (Zac 11:17), los medicos inutiles de Job (Job 13:4) y la adivinacion vana de Jeremias (Jer 14:14) usan la palabra para describir vaciedad y futilidad mas que un idolo concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0458', 'spa', 'Elimélec, ''Dios es rey''; esposo de Noemí que emigró a Moab durante una hambruna en Belén.', 'Nombre propio teofórico que significa ''Dios es rey'' o ''mi Dios es rey'', combinando אֵל (''Dios'') y מֶלֶךְ (''rey''). Elimélec es el esposo de Noemí y padre de Mahlón y Quelión en el libro de Rut. Impulsado por la hambruna, trasladó a su familia de Belén a Moab, donde murió (Rut 1:2-3). Su nombre encierra una profunda ironía: el hombre cuyo nombre proclama la soberanía divina muere en tierra extranjera, pero la providencial realeza de Dios se despliega precisamente a través del linaje familiar que él dejó atrás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0459', 'spa', 'Pronombre demostrativo arameo ''estos/estas'', usado exclusivamente en Daniel para referencia plural.', 'Pronombre demostrativo arameo que significa ''estos'' o ''estas'', y funciona como la forma plural de דְּנָה (''este/esta''). Se encuentra únicamente en las porciones arameas de Daniel, donde señala grupos ya introducidos en el contexto: reinos, sátrapas o bestias. Las traducciones multilingües convergen notablemente: español ''estos/estas'', francés ''ces'' y alemán ''diese'', todas lo presentan como un demostrativo plural directo, confirmando su función referencial sencilla y sin complicaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0460', 'spa', 'Eliasaf, ''Dios ha añadido''; un jefe gadita y un líder levítico en el período del desierto.', 'Nombre propio teofórico que significa ''Dios ha añadido'', combinando אֵל (''Dios'') y יָסַף (''añadir''). Dos personas llevan este nombre en Números: el hijo de Deuel (o Reuel), jefe de la tribu de Gad durante el censo y la marcha por el desierto (Nm 1:14; 2:14; 7:42, 47; 10:20), y el hijo de Lael, jefe del clan gersonita de los levitas, responsable de las cubiertas del tabernáculo (Nm 3:24). Ambas figuras desempeñan funciones administrativas y litúrgicas durante el período formativo de Israel en el desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0461', 'spa', 'Eliezer — nombre propio que significa ''mi Dios es ayuda'', llevado por varias figuras del AT, incluyendo el mayordomo de Abraham. Nombre teofórico comp', 'Eliezer — nombre propio que significa ''mi Dios es ayuda'', llevado por varias figuras del AT, incluyendo el mayordomo de Abraham. Nombre teofórico compuesto de ''El'' (Dios) y ''ezer (ayuda), que significa ''mi Dios es ayuda''. El portador más antiguo y conocido es el mayordomo de la casa de Abraham, procedente de Damasco, mencionado como su posible heredero antes de la promesa de Isaac (Gn 15:2). Moisés nombró a su segundo hijo Eliezer, conmemorando la liberación divina de la espada del faraón (Éx 18:4). El nombre reaparece en Crónicas, Esdras y 2 Crónicas para un guerrero benjaminita (1 Cr 7:8), varios sacerdotes y levitas (1 Cr 15:24; 26:25; Esd 8:16; 10:18, 23, 31), un jefe rubenita (1 Cr 27:16) y un profeta que reprendió a Josafat por su alianza con Ocozías (2 Cr 20:37).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0464', 'spa', 'Elifaz — posiblemente ''Dios es oro fino'', nombre del primogénito de Esaú y del principal consejero de Job. Elifaz (posiblemente ''Dios es oro fino'') es', 'Elifaz — posiblemente ''Dios es oro fino'', nombre del primogénito de Esaú y del principal consejero de Job. Elifaz (posiblemente ''Dios es oro fino'') es compartido por dos figuras prominentes. El primero es el primogénito de Esaú con Ada, cuyos descendientes se convirtieron en jefes edomitas (Gn 36:4-16; 1 Cr 1:35-36). El segundo es Elifaz el temanita, el amigo mayor de Job, que pronuncia tres ciclos de discursos (Job 4-5; 15; 22) argumentando que el sufrimiento implica pecado oculto. La reprensión de Dios recae específicamente sobre Elifaz y sus compañeros (Job 42:7, 9). Notablemente, Temán era territorio edomita, lo que sugiere que el Elifaz de Job podría descender del esauíta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0467', 'spa', 'Elifelet, nombre hebreo que significa «mi Dios es liberación», portado por varios personajes bíblicos.', 'Nombre propio teofórico que combina «El» (Dios) y «pelet» (liberación), con el significado «mi Dios es liberación». Lo llevan al menos cinco individuos en la Biblia hebrea, siendo el más notable un hijo de David nacido en Jerusalén (2 S 5:16; 1 Cr 3:6, 8; 14:7). Otros portadores incluyen uno de los valientes de David (2 S 23:34), un benjaminita descendiente de Saúl (1 Cr 8:39) y dos hombres en la comunidad postexílica de Esdras (Esd 8:13; 10:33). El nombre aparece con variantes ortográficas, incluyendo אֶלְפָּלֶט.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0468', 'spa', 'Elisur (''mi Dios es una roca''), jefe de la tribu de Ruben durante la peregrinacion por el desierto.', 'Nombre propio teoforico que significa ''mi Dios es una roca'', llevado por el principe de la tribu de Ruben durante la travesia del desierto. El nombre combina אֵל (Dios) con צוּר (roca), haciendose eco de la confesion de Deuteronomio 32:4 que proclama a Dios como la Roca. Elisur aparece exclusivamente en Numeros (1:5; 2:10; 7:30, 35; 10:18) en listas censales y registros de ofrendas tribales, siempre en su funcion oficial como lider designado de Ruben.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0469', 'spa', 'Elisafán — nombre propio que significa ''Dios ha protegido'', llevado por un jefe coatita y un líder zebulonita.', 'Elisafán (también escrito Elzafán) es un nombre propio masculino compuesto de ''El'' (Dios) y ''tsafán'' (esconder, proteger), con el significado de ''Dios ha protegido''. El nombre pertenece al menos a dos personajes bíblicos: un jefe levita coatita designado durante el período del desierto (Num 3:30), que más tarde aparece en las disposiciones musicales del templo bajo David (1 Cr 15:8) y en las reformas de Ezequías (2 Cr 29:13); y un líder tribal de Zabulón encargado del reparto de la tierra de Canaán (Num 34:25). La forma alternativa Elzafán aparece en Éxodo 6:22 y Levítico 10:4, donde Elisafán y su hermano Misael retiran los cuerpos de Nadab y Abiú del tabernáculo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0471', 'spa', 'Eliaquim — ''Dios levanta''; nombre propio llevado por el mayordomo de Ezequías y como nombre original del rey Joacim. Eliaquim (hebreo אֶלְיָקִים, ''Dio', 'Eliaquim — ''Dios levanta''; nombre propio llevado por el mayordomo de Ezequías y como nombre original del rey Joacim. Eliaquim (hebreo אֶלְיָקִים, ''Dios levanta'') es un nombre propio teofórico llevado por al menos dos figuras prominentes del Antiguo Testamento: (1) hijo de Hilcías, quien sirvió como mayordomo del palacio del rey Ezequías y fue el negociador principal durante el asedio asirio de Jerusalén (2 R 18:18, 26, 37; Is 22:20; 36:3, 11, 22; 37:2); y (2) el nombre de nacimiento original de Joacim hijo de Josías, cambiado por el faraón Necó cuando lo instaló como rey vasallo de Judá (2 R 23:34; 2 Cr 36:4). El oráculo de Isaías sobre Eliaquim el mayordomo (Is 22:20-25) lo retrata como una ''estaca en lugar firme'', al que se le confía la llave de la casa de David, lenguaje que resuena en Apocalipsis 3:7.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0473', 'spa', 'Elisá (descendiente de Javán; posiblemente Eólida, Hélade o territorios itálicos)', 'Descendiente de Javán incluido en la Tabla de las Naciones, que representa un pueblo o región de donde provenían materiales valiosos. Los estudiosos han propuesto diversas identificaciones: Eólida en Asia Menor, la Hélade (Grecia), e incluso Italia y Sicilia. Ezequiel menciona «las costas de Elisá» como fuente de tinte púrpura, lo que sugiere conexiones de comercio marítimo. La incertidumbre sobre su identificación refleja cómo las antiguas redes comerciales ponían a Israel en contacto con pueblos mediterráneos distantes, algunos cuya ubicación exacta se ha perdido en la historia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0475', 'spa', 'Eliasib — nombre propio que significa ''Dios restaura'', llevado por seis personajes del AT incluyendo el sumo sacerdote de Nehemias. Nombre teoforico c', 'Eliasib — nombre propio que significa ''Dios restaura'', llevado por seis personajes del AT incluyendo el sumo sacerdote de Nehemias. Nombre teoforico compuesto de ''El'' (Dios) y una forma de shub (volver, restaurar), que significa ''Dios restaura''. El portador mas prominente es el sumo sacerdote durante la gobernacion de Nehemias, quien dirigio la reconstruccion de la Puerta de las Ovejas (Neh 3:1), pero controversialmente proporciono a Tobias el amonita una camara en los atrios del templo (Neh 13:4-7). Otros portadores incluyen un descendiente davidico (1 Cro 3:24), un jefe de division sacerdotal (1 Cro 24:12), un cantor del templo que se habia casado con mujer extranjera (Esd 10:24) y dos laicos de los clanes de Zatu y Bani que hicieron lo mismo (Esd 10:27, 36). La resonancia ironica del nombre — ''Dios restaura'' — se entreteje con la narrativa de restauracion postexilica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0476', 'spa', 'Elisama -- nombre propio que significa ''Dios ha oído'', llevado por seis figuras del AT incluyendo un jefe efraimita', 'Elisama -- nombre propio que significa ''Dios ha oído'', llevado por seis figuras del AT incluyendo un jefe efraimita');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0477', 'spa', 'Eliseo — el profeta de Israel que sucedió a Elías, conocido por sus hechos milagrosos en el reino del norte', 'Eliseo — el profeta de Israel que sucedió a Elías, conocido por sus hechos milagrosos en el reino del norte');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0479', 'spa', 'Estos, aquellos — pronombre demostrativo arameo (plural) usado en Daniel y Esdras. Pronombre demostrativo arameo que significa ''estos'' o ''aquellos'', f', 'Estos, aquellos — pronombre demostrativo arameo (plural) usado en Daniel y Esdras. Pronombre demostrativo arameo que significa ''estos'' o ''aquellos'', forma plural de dēk (''aquel''). Aparece exclusivamente en las porciones arameas de la Biblia hebrea — Daniel y Esdras — donde funciona como demostrativo plural estándar que modifica sustantivos. La frase característica guvrāyyā'' illēk (''estos hombres'') se repite a lo largo de Daniel 3 en la historia del horno de fuego (vv. 12, 13, 21, 22, 23, 27), y de nuevo en Daniel 6 respecto a los conspiradores contra Daniel. En Esdras modifica asuntos de interés administrativo: ''esta casa'' y ''estos ancianos'' (Esd 4:21; 5:9; 6:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0481', 'spa', 'Atar; en Nifal, estar atado (de la lengua): enmudecer, callar; en Piel, atar gavillas.', 'En su raíz, אָלַם significa «atar», y sus diversas conjugaciones irradian desde esa imagen física. El Nifal —con mucho la forma más frecuente— presenta la lengua como atada: silenciada, enmudecida. Este es el verbo detrás de la conmovedora imagen de Isaías 53:7, donde el Siervo Sufriente calla ante sus trasquiladores, y del silencio impuesto divinamente a Ezequiel (Ez 3:26; 24:27). El salmista lo usa para la contención deliberada: «enmudecí con silencio» (Sal 39:2). Una única aparición en Piel en Génesis 37:7 conserva el significado raíz concreto: los hermanos de José atando gavillas en el campo, recordándonos que el silencio espiritual y la atadura física comparten una misma raíz hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0483', 'spa', 'Mudo, incapaz de hablar; usado literalmente de personas y figuradamente de centinelas e ídolos.', 'Adjetivo que describe la incapacidad de hablar, abarcando tanto la mudez física como el silencio figurado. En Éxodo 4:11, Dios se declara soberano sobre quién es hecho mudo o vidente, arraigando el término en la realidad de la condición humana. Isaías 35:6 promete que el mudo cantará de gozo en la era mesiánica, mientras que Isaías 56:10 invierte la imagen con dureza: los centinelas de Israel son ''perros mudos'' que no pueden ladrar, una metáfora devastadora del fracaso profético. Habacuc 2:18 aplica el término a los ídolos, exponiendo lo absurdo de consultar a un maestro sin voz. El campo semántico se concentra en una sola idea: la ausencia de voz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0484', 'spa', 'madera de almug (variante de algum; madera preciosa importada)', 'Madera preciosa importada por mar desde Ofir, utilizada por Salomón para mobiliario del templo e instrumentos musicales. Esta es la grafía de Reyes para lo que Crónicas llama algum (H0418): el mismo material con una leve variación ortográfica. Su asociación con el oro y las piedras preciosas indica su alto valor. Salomón la empleó para fabricar balaustradas del templo y del palacio, además de liras y arpas para los músicos. El texto señala que nunca antes se había visto tal madera en Israel, subrayando su rareza exótica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0485', 'spa', 'Gavilla de grano cosechado, memorable en el sueno de Jose y en el retorno del exilio.', 'Designa un manojo atado de tallos de grano cosechado, es decir, una gavilla. Cuatro de sus cinco apariciones se encuentran en el sueno profetico de Jose (Gn 37:7), donde su gavilla se levanta erguida y las gavillas de sus hermanos se inclinan ante ella, prefigurando su futura autoridad. La aparicion final en el Salmo 126:6 emplea las gavillas como imagen gozosa del retorno del cautiverio: los que siembran con lagrimas cosecharan con regocijo, trayendo sus gavillas consigo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0490', 'spa', 'Viuda, mujer desamparada; posiblemente un homógrafo que significa palacio o fortaleza (Is 13:22)', 'Viuda, mujer desamparada; posiblemente un homógrafo que significa palacio o fortaleza (Is 13:22)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0491', 'spa', 'Viudez; el estado social y personal de ser viuda', 'Sustantivo femenino que designa la condición de viudez, no simplemente la pérdida del esposo sino toda la realidad social de vulnerabilidad y cambio de estatus que conllevaba en el antiguo Cercano Oriente. Tamar se pone y se quita sus ''vestidos de viudez'' como marca de su identidad restringida (Gn 38:14, 19). Las concubinas recluidas de David viven en ''viudez de vida'', vivas pero prácticamente viudas (2 S 20:3). De manera aún más llamativa, Dios promete a la Jerusalén restaurada que no recordará más ''la afrenta de tu viudez'' (Is 54:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0492', 'spa', 'fulano, tal y tal, persona o lugar sin nombre (designador indefinido)', 'Término indefinido que significa «fulano» o «tal y tal», empleado cuando el hablante omite deliberadamente un nombre. En Rut, Booz se dirige a un pariente redentor anónimo llamándolo «fulano» (literalmente «tal y tal»). Samuel y Reyes lo usan para lugares sin nombre cuando la ubicación exacta se omite por razones estratégicas o narrativas. El término funciona como el «fulano de tal» o «tal lugar» en español: reconoce la existencia de alguien o algo sin especificar su identidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0494', 'spa', 'Elnatán (''Dios ha dado''), nombre propio del abuelo de Joaquín y de levitas en tiempos de Esdras.', 'Nombre propio masculino que significa ''Dios ha dado'', imagen especular de Netanel (''dado por Dios''). El Elnatán más prominente es el hijo de Acbor, abuelo del rey Joaquín (2 R 24:8), quien aparece en Jeremías como un funcionario de la corte enviado a recuperar al profeta Urías de Egipto (Jer 26:22) y como uno de los presentes durante la lectura del rollo de Jeremías (Jer 36:12, 25). Tres hombres llamados Elnatán figuran también entre los líderes que Esdras convocó antes del regreso de Babilonia (Esd 8:16). El nombre teofórico tiene paralelos acadios, fenicios y palmirenos, lo que subraya su amplia difusión semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0499', 'spa', 'Eleazar — ''Dios ha ayudado''; nombre propio llevado por el hijo de Aarón, el sumo sacerdote, y por varias figuras bíblicas posteriores', 'Eleazar — ''Dios ha ayudado''; nombre propio llevado por el hijo de Aarón, el sumo sacerdote, y por varias figuras bíblicas posteriores');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0500', 'spa', 'Elealé, ciudad moabita cercana a Hesbon asignada a la tribu de Ruben.', 'Toponimo que significa quizas ''Dios asciende'', identificando una aldea en el territorio de Ruben cerca de Hesbon en Transjordania. Aparece primero en el registro de la asignacion tribal (Nm 32:3, 37) y posteriormente en los oraculos profeticos contra Moab (Is 15:4; 16:9; Jer 48:34), donde su devastacion senala el juicio divino. El sitio se identifica con la moderna el-Al, al noreste de Hesbon.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0501', 'spa', 'Elasá — nombre propio que significa ''Dios ha hecho'', llevado por cuatro hombres en Crónicas, Esdras y Jeremías.', 'Elasá es un nombre propio masculino que significa ''Dios ha hecho'', formado a partir de ''El'' (Dios) y ''asá'' (hacer). Aparece en cuatro contextos genealógicos y narrativos distintos: un descendiente de Judá por la línea de Sesán (1 Cr 2:39-40), un benjamita de la familia de Saúl (1 Cr 8:37; 9:43), un sacerdote del linaje de Pasur que se había casado con una mujer extranjera (Esd 10:22), y un hijo de Safán que llevó la carta de Jeremías a los exiliados en Babilonia (Jer 29:3). La estructura teofórica del nombre es paralela a muchos nombres hebreos que celebran la acción creadora de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0502', 'spa', 'Aprender (Qal); enseñar, instruir (Piel) — adquirir o transmitir conocimiento y destreza', 'Verbo que significa ''aprender'' en el Qal y ''enseñar'' en el Piel, emparentado con el arameo אלף (aprender) y el árabe ''alifa (familiarizarse). Aunque aparece solo cuatro veces en la Biblia hebrea, todas en literatura sapiencial, posee una fuerza expresiva notable. Elifaz acusa la iniquidad de Job de ''enseñar'' a su boca el engaño (Job 15:5), Elihú se ofrece a ''enseñarle'' sabiduría (Job 33:33), y Dios es alabado como Aquel que ''nos enseña'' más que a las bestias (Job 35:11). La única aparición en Qal advierte contra aprender las costumbres del hombre iracundo (Pr 22:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0504', 'spa', 'Ganado vacuno, bueyes (usados en agricultura); también clan o subdivisión tribal en Israel.', 'Este sustantivo es el homónimo menos frecuente de אֶלֶף (mil), y se refiere al ganado vacuno doméstico empleado para arar y labrar la tierra. El plural אֲלָפִים aparece en contextos de bendición agrícola: el aumento del rebaño es señal del favor divino (Dt 7:13; 28:4). El Salmo 8:7 sitúa a los bueyes bajo el dominio humano junto con las ovejas y los animales salvajes. Un sentido secundario, presente en Jueces 6:15, emplea אֶלֶף para referirse a un clan o subdivisión tribal, cuando Gedeón protesta diciendo que su clan es el más débil de Manasés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0505', 'spa', 'Mil (numeral); en dual ''dos mil''; en plural ''miles/millares''; también ''clan, subdivisión tribal''.', 'Una palabra que cuenta tanto personas como comunidades. En su sentido numérico directo, אֶלֶף significa ''mil'' y aparece en censos, recuentos de batalla y mediciones a lo largo de toda la Biblia hebrea. Pero un fascinante sentido secundario --''clan'' o ''subdivisión tribal''-- podría replantear algunas de las cifras notoriamente elevadas del Antiguo Testamento. Cuando Gedeón dice en Jue 6:15 ''mi אֶלֶף es el más débil de Manasés'', se refiere a su clan, no a un millar literal. Algunos eruditos sostienen que muchos totales militares en Números y Crónicas contaban originalmente ''clanes'' en vez de ''miles'', lo cual reduciría drásticamente las cifras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0506', 'spa', 'Numeral arameo ''mil'', usado en Daniel para grandes cantidades y multitudes.', 'La forma aramea del numeral ''mil'', equivalente al hebreo אֶלֶף. Las cinco apariciones se encuentran en Daniel: el banquete de Belsasar para mil nobles (Dn 5:1) y la vision del trono de Dios atendido por ''millares de millares'' (Dn 7:10). La forma enfatica אַלְפָא en Daniel 5:1 se refiere al millar especifico recien mencionado. El espanol ''mil'', el frances ''mille'' y el aleman ''tausend'' traducen uniformemente el valor numerico directo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0508', 'spa', 'Elpaal (nombre benjaminita, probablemente «Dios del hacer» o «Dios ha actuado»)', 'Antepasado benjaminita mencionado en las genealogías de Crónicas, cuyo nombre probablemente significa «Dios del hacer» o «Dios ha actuado». El nombre sigue los patrones teofóricos hebreos típicos, incorporando una confesión de la acción divina en la identidad personal. Crónicas conserva este nombre como parte de los registros familiares postexílicos de Benjamín, manteniendo la memoria tribal mediante una cuidadosa documentación genealógica. Como muchos nombres en las listas genealógicas, Elpaal no recibe elaboración narrativa alguna, pero su nombre testifica la fe de su familia en que Dios actúa con propósito en la historia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0511', 'spa', 'Elcaná (''Dios ha adquirido''); nombre de varias figuras del AT, principalmente el padre del profeta Samuel.', 'Elcaná (''Dios ha adquirido''); nombre de varias figuras del AT, principalmente el padre del profeta Samuel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0516', 'spa', 'No destruyas — yusivo Hifil negado de שָׁחַת, fórmula en encabezados de Salmos (''Al-Tashcheth'').', 'Esta forma es el yusivo Hifil negado de שָׁחַת (''destruir, arruinar''), que aparece en la inscripción litúrgica אַל־תַּשְׁחֵת (''No destruyas'') presente en los Salmos 57, 58, 59 y 75. La frase probablemente designa el nombre de una melodía o una instrucción litúrgica, posiblemente en eco de la súplica intercesora de Moisés en Deuteronomio 9:26. El español lo traduce como ''no destruyas'', conservando la fuerza prohibitiva urgente del yusivo hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0517', 'spa', 'Madre; progenitora femenina de seres humanos; también la madre de un animal en contextos legales y cultuales.', 'אֵם es una de las palabras más primordiales en cualquier lengua, y el hebreo no es la excepción. Designa a la madre biológica y social: Eva como ''madre de todos los vivientes'' (Gn 3:20), Rebeca guiando a Jacob (Gn 27:13), las madres dolientes de Jeremías y Lamentaciones. En tres ocurrencias especializadas (Éx 23:19; 34:26; Dt 22:6-7), la palabra se extiende a las madres animales, enraizando las leyes de compasión de Israel en el vínculo entre la madre y su cría. En todas las lenguas --árabe umm, arameo imma, español madre, francés mère-- la calidez y el peso de esta palabra son universalmente reconocidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0518a', 'spa', 'Particula condicional: si; disyuntiva: o; interrogativa indirecta: si acaso; concesiva: aunque; aseverativa: ciertamente', 'Uno de los conectores logicos mas versatiles del hebreo biblico, אִם funciona primariamente como el condicional ''si'' que introduce casi toda protasis del Antiguo Testamento. Mas alla de la condicionalidad, se ramifica hacia la disyuncion (''o'', especialmente en construcciones pareadas אִם...אִם), las preguntas indirectas (''si acaso'') e incluso la fuerza retorica. En formulas de juramento porta una negacion implicita --''si hago esto'' equivale a ''ciertamente no lo hare''--, uso preservado en el arabe إن y el arameo אֵן. Sus 922 apariciones tocan practicamente todo genero de la prosa y poesia biblicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0518b', 'spa', 'Partícula compuesta כִּי אִם: si, solo/excepto, sino/más bien, ciertamente; en condiciones, restricciones, adversativas y juramentos.', 'Un compuesto bipartito (כִּי + אִם) cuyo significado varía drásticamente según el contexto sintáctico. Cuando cada partícula conserva su fuerza independiente, כִּי אִם introduce una condición genuina (''que si'', ''pues si''). Pero en la gran mayoría de sus aproximadamente 140 ocurrencias, ambas partículas se fusionan en una unidad restrictiva o adversativa: tras una negación significa ''excepto, solo, sino'' (לֹא ... כִּי אִם, ''no ... sino''), y en fórmulas de juramento porta fuerza aseverativa: ''ciertamente''. Su versatilidad lo convierte en uno de los marcadores discursivos más sensibles al contexto del hebreo bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0519', 'spa', 'amah -- sierva, criada; usado tanto como término de estatus social como forma humilde de autodirección', 'amah -- sierva, criada; usado tanto como término de estatus social como forma humilde de autodirección');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0520a', 'spa', 'Codo; unidad de medida lineal (aprox. 45 cm / 18 pulgadas), la dimensión estándar para construcción, distancia y profundidad.', 'אַמָּה es la unidad de longitud cotidiana en toda la Biblia hebrea, derivada del antebrazo (del codo a la punta de los dedos) y presente en prácticamente todo proyecto constructivo, medición y descripción espacial de la Escritura. Mide el arca de Noé (Gn 6:15), el tabernáculo y su mobiliario (Éx 25-27), el templo de Salomón (1 R 6) y el templo visionario de Ezequiel (Ez 40-48). Dos variantes menores aparecen en los márgenes: en Dt 3:11, ''el codo de un hombre'' especifica un estándar frente al posible codo real más largo, y en Jr 51:13 la palabra podría funcionar metonímicamente como ''medida'' en sentido amplio. Pero en 246 de 248 ocurrencias el significado es simplemente la unidad lineal concreta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0521', 'spa', 'Codo (arameo); unidad estándar de medida lineal, aproximadamente 45 cm / 18 pulgadas', 'Palabra aramea para ''codo'', la unidad fundamental de longitud en el antiguo Cercano Oriente, equivalente a la distancia del codo a la punta de los dedos (aproximadamente 45 centímetros). Aparece exclusivamente en las porciones arameas de la Biblia hebrea: en las dimensiones de la imagen de oro de Nabucodonosor, de sesenta codos de altura y seis de anchura (Dn 3:1), y en el decreto de Ciro que especifica sesenta codos de alto y de ancho para el templo reconstruido (Esd 6:3). La forma plural אַמִּין refleja los cognados siríacos y targúmicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0523', 'spa', 'tribus, pueblos, naciones (grupos colectivos con identidad compartida)', 'Término que designa tribus o pueblos, resaltando su identidad colectiva y organización social. En Génesis se emplea para las divisiones tribales de los descendientes de Ismael, mientras que en Números se aplica a la estructura tribal madianita. Los Salmos amplían su alcance para abarcar a todos los pueblos llamados a alabar a Dios, apareándolo con «naciones» en paralelismo poético. La raíz se vincula con la palabra árabe para comunidad o pueblo religioso, subrayando la cohesión social y a veces cultual que define a estos grupos. El término ocupa un lugar intermedio entre los clanes familiares y las entidades nacionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0524', 'spa', 'Nación, pueblo, tribu — término colectivo para grupos étnicos o políticos, en hebreo bíblico tardío y arameo.', 'Este sustantivo designa una nación o grupo étnico, y aparece principalmente en las secciones arameas de Daniel y Esdras. En las escenas cortesanas de Daniel, los heraldos convocan a ''pueblos, naciones y lenguas'' (Dn 3:4, 7; 5:19; 6:25; 7:14), mientras que Esdras 4:10 enumera naciones deportadas. El Salmo 117:1 ofrece la única aparición en hebreo, invitando a todas las naciones a alabar al SEÑOR. La fórmula tripartita aramea de Daniel subraya la universalidad imperial del dominio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0526', 'spa', 'Amón -- nombre propio que significa ''artesano maestro'' o ''fiel'', llevado por un rey de Judá y otros', 'Amón -- nombre propio que significa ''artesano maestro'' o ''fiel'', llevado por un rey de Judá y otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0529', 'spa', 'Fidelidad, confiabilidad; la cualidad de ser fiable y constante.', 'Describe la cualidad de ser digno de confianza y fiable. En Deuteronomio 32:20, su forma negativa diagnostica el fracaso de Israel: hijos ''en quienes no hay fidelidad''. Proverbios lo emplea para caracterizar al mensajero leal (13:17), al testigo fiel (14:5) y a la persona integra (20:6). Isaias 26:2 corona el concepto: la nacion justa que ''guarda la fidelidad'' podra entrar en la ciudad de Dios. El espanol ''fidelidad'' y el aleman ''Treue'' captan este sentido nuclear de fiabilidad probada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0530', 'spa', 'Fidelidad, lealtad, confiabilidad; también fe/confianza personal y firmeza física', 'Fidelidad, lealtad, confiabilidad; también fe/confianza personal y firmeza física');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0531', 'spa', 'Amoz — padre del profeta Isaías. Los 13 casos en la Biblia hebrea aparecen exclusivamente en la fórmula patronímica ''Isaías hijo de Amoz'', tanto en lo', 'Amoz — padre del profeta Isaías. Los 13 casos en la Biblia hebrea aparecen exclusivamente en la fórmula patronímica ''Isaías hijo de Amoz'', tanto en los encabezados proféticos (Isa 1:1; 2:1; 13:1; 20:2; 37:2, 21; 38:1) como en las narraciones históricas de Reyes y Crónicas (2 Re 19:2, 20; 20:1; 2 Cr 26:22; 32:20, 32). El nombre (que significa ''fuerte'' o ''valiente'', de la raíz אמץ) no aporta información adicional sobre la persona; Amoz es conocido enteramente a través de su hijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0533', 'spa', 'Poderoso, fuerte, valiente; describe personas, fuerzas o la fuerza irresistible de Dios.', 'Adjetivo que transmite poder formidable y valor resuelto. Describe cómo la conspiración de Absalón se hacía ''fuerte'' (2 Sam 15:12), presenta a Dios como ''sabio de corazón y poderoso en fuerza'' (Job 9:4, 19) y retrata al invasor asirio como instrumento feroz de Dios (Is 28:2). En Amós 2:16, el ''esforzado de corazón'' —el guerrero más valiente— huirá desnudo en el día del juicio. Isaías 40:26 lo aplica a Dios, que despliega las estrellas por la grandeza de su poder: ninguna falta. El término converge en la idea de una fuerza abrumadora e irresistible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0535', 'spa', 'Languidecer, marchitarse, debilitarse; dicho de la tierra, la vegetación o las personas que pierden vitalidad y fuerza bajo el juicio divino o la adve', 'Languidecer, marchitarse, debilitarse; dicho de la tierra, la vegetación o las personas que pierden vitalidad y fuerza bajo el juicio divino o la adversidad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0539', 'spa', 'Creer, ser fiel, sostener; abarca la confianza cognitiva, la fidelidad firme y la crianza parental.', 'Una raíz de extraordinaria riqueza semántica cuyos significados irradian desde una idea nuclear de firmeza. En Hifil expresa el acto de creer o depositar confianza en alguien, como cuando Abraham creyó al SEÑOR en Génesis 15:6, versículo cuyo peso teológico se siente en todo el canon. El participio Nifal produce el sentido adjetival ''fiel, digno de confianza'', describiendo el carácter perdurable del pacto de Dios (Dt 7:9) y a siervos confiables como Moisés (Nm 12:7). Notablemente, el participio Qal se desplaza al ámbito concreto de la crianza: un padre adoptivo o nodriza que ''afirma'' cargando y alimentando, como Noemí hizo con Obed (Rt 4:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0540', 'spa', 'confiar, ser digno de confianza (arameo: tener fe o resultar fiel)', 'Verbo arameo que aparece en Daniel y significa confiar o ser digno de confianza. Daniel emplea tanto formas activas como pasivas: Daniel mismo confió en su Dios y fue librado de los leones, mientras que la interpretación dada a Nabucodonosor resultó fidedigna. La raíz es el equivalente arameo del hebreo «amén», esa cualidad firme, confiable y segura que caracteriza tanto la fidelidad divina como la respuesta humana de confianza plena. Es lenguaje de pacto trasladado al arameo, manteniendo la continuidad teológica aun en el cambio lingüístico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0543', 'spa', 'Amén; afirmación solemne de verdad, acuerdo o alabanza doxológica — ''en verdad,'' ''así sea,'' ''que permanezca.''', 'Amén; afirmación solemne de verdad, acuerdo o alabanza doxológica — ''en verdad,'' ''así sea,'' ''que permanezca.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0550', 'spa', 'Amnón; nombre propio que significa ''fiel,'' llevado principalmente por el hijo mayor de David y un descendiente de Judá.', 'Amnón; nombre propio que significa ''fiel,'' llevado principalmente por el hijo mayor de David y un descendiente de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0551', 'spa', 'Verdaderamente, ciertamente; adverbio de afirmación enfática usado en aseveraciones y preguntas retóricas.', 'Adverbio derivado de la raíz אמן (''ser firme, digno de confianza''), empleado para afirmar la verdad de una declaración con fuerza enfática. Aparece tanto en afirmaciones sinceras como en preguntas retóricas irónicas. En Rut 3:12, Boaz afirma solemnemente su condición de pariente redentor: ''verdaderamente yo soy redentor.'' En Job, suele llevar un tono sarcástico: Job 12:2 declara con ironía ''¡verdaderamente vosotros sois el pueblo, y con vosotros morirá la sabiduría!'' El español distingue matices con ''verdaderamente'' y ''de verdad''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0552', 'spa', 'Adverbio enfatico que significa ''de verdad, ciertamente, acaso,'' usado siempre en preguntas retoricas o de incredulidad.', 'Un adverbio enfatico que expresa sorpresa genuina o duda retorica, apareciendo exclusivamente en preguntas. Cuando Sara rie ante la promesa de un hijo, Dios pregunta a Abraham: ''¿De verdad dara a luz Sara?'' (Gn 18:13). Balac desafia a Balaam con la misma palabra (Nm 22:37), y Salomon se maravilla preguntando si Dios ''verdaderamente'' habitara en la tierra (1 R 8:27). Derivado de אָמֵן con la terminacion adverbial -am, este vocablo canaliza toda su fuerza hacia la interrogacion, nunca aparece en enunciados declarativos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0553', 'spa', 'Ser fuerte, valiente o firme; en Piel, fortalecer, animar o endurecer; reflexivamente, mostrar resolución o determinación.', 'Ser fuerte, valiente o firme; en Piel, fortalecer, animar o endurecer; reflexivamente, mostrar resolución o determinación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0558', 'spa', 'Amasías — nombre teofórico que significa ''Yah(weh) es poderoso'', llevado por un rey de Judá y varios otros personajes.', 'Amasías — nombre teofórico que significa ''Yah(weh) es poderoso'', llevado por un rey de Judá y varios otros personajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0559', 'spa', 'Decir, hablar, contar; pensar interiormente; declarar o proclamar formalmente', 'El verbo אָמַר es la palabra primaria para el habla en la Biblia hebrea, introduciendo el discurso directo miles de veces con la formula narrativa וַיֹּאמֶר (''y dijo''). Mas alla del habla ordinaria, puede volverse hacia el interior para describir el pensamiento o la deliberacion privada --''dije en mi corazon''--, uso atestiguado desde Genesis hasta los Salmos. En sus formas mas raras del Hifil y enfaticas, se eleva a la declaracion formal o proclamacion publica, como cuando Israel ''declaro'' que el SENOR era su Dios (Dt 26:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0560', 'spa', 'Decir, hablar, contar; mandar u ordenar; en voz pasiva, ser dicho o llamado (arameo)', 'Decir, hablar, contar; mandar u ordenar; en voz pasiva, ser dicho o llamado (arameo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0561', 'spa', 'Palabra, dicho, expresión; término poético para palabras habladas, discurso divino o decreto autoritativo', 'Palabra, dicho, expresión; término poético para palabras habladas, discurso divino o decreto autoritativo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0562', 'spa', 'Palabra, discurso, declaración; sinónimo poético de דָּבָר usado del habla humana y las promesas divinas.', 'Sustantivo masculino empleado casi exclusivamente en poesía, que funciona como sinónimo elevado de דָּבָר (palabra). En los Salmos describe el ''habla'' que un día transmite al otro (Sal 19:2-3) y la promesa firme de Dios (Sal 77:8). Job lo usa para los argumentos humanos y los decretos autoritativos de Dios (Job 22:28). Proverbios lo empareja con ''mandamiento'' para instar a la recepción atenta de la enseñanza sabia (Pr 2:1; 7:1). El vocablo conlleva un peso de deliberación: no se trata de comentarios casuales sino de pronunciamientos solemnes. Su restricción a la prosa poética y elevada (incluyendo Jos 24:27) lo marca como término de dignidad literaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0563', 'spa', 'corderos (arameo: ovejas jóvenes destinadas al sacrificio)', 'Ovejas jóvenes destinadas a las ofrendas sacrificiales en el templo restaurado, mencionadas en las secciones arameas de Esdras. Estos corderos servían como holocaustos y ofrendas por el pecado durante la rededicación del templo y el culto continuo. Las autoridades persas financiaron su provisión, permitiendo a los exiliados que retornaron mantener un culto sacrificial apropiado. El término representa la continuidad con la práctica israelita antigua, incluso cuando el idioma había cambiado al arameo y la autoridad política descansaba en reyes extranjeros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0564', 'spa', 'Imer — nombre de familia sacerdotal; un turno sacerdotal y sus descendientes desde el templo hasta el período postexílico. El nombre אִמֵּר (Imer) des', 'Imer — nombre de familia sacerdotal; un turno sacerdotal y sus descendientes desde el templo hasta el período postexílico. El nombre אִמֵּר (Imer) designa uno de los veinticuatro turnos sacerdotales organizados bajo David (1 Cr 24:14) y la familia descendiente de él. Miembros de la casa de Imer aparecen a lo largo de la historia cúltica de Israel: sirviendo en el templo preexílico (1 Cr 9:12; Jer 20:1, donde Pasur hijo de Imer es ''oficial principal en la casa del SEÑOR''), regresando del exilio babilónico en número significativo (Esd 2:37; Neh 7:40 — más de mil hombres) y enfrentando la crisis de los matrimonios mixtos (Esd 10:20). Una localidad llamada Imer también se menciona entre los lugares de los cuales los exiliados que regresaron no pudieron verificar su ascendencia israelita (Esd 2:59; Neh 7:61).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0565a', 'spa', 'Dicho, palabra o declaración — especialmente la palabra o promesa de Dios en la poesía; también discurso general o humano en lenguaje poético.', 'Dicho, palabra o declaración — especialmente la palabra o promesa de Dios en la poesía; también discurso general o humano en lenguaje poético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0567', 'spa', 'Amorreo — un pueblo cananeo que habitaba ambos lados del Jordán antes de la conquista israelita', 'Amorreo — un pueblo cananeo que habitaba ambos lados del Jordán antes de la conquista israelita');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H0568', 'spa', 'Amarías -- ''YHWH ha hablado/prometido'', nombre propio llevado por sacerdotes, levitas y laicos', 'Amarías -- ''YHWH ha hablado/prometido'', nombre propio llevado por sacerdotes, levitas y laicos');